#!/usr/bin/env node

/**
 * Simplified Agent CLI for Indie Developers
 * 
 * 5 questions max, opinionated defaults, fast setup
 */

const readline = require('readline');
const fs = require('fs').promises;
const path = require('path');

class SimpleAgentCLI {
  constructor() {
    this.rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });
  }

  async prompt(question, options = null, defaultIndex = 0) {
    return new Promise((resolve) => {
      let fullQuestion = question;
      if (options && options.length > 0) {
        fullQuestion += `\n${options.map((opt, idx) => `${idx + 1}) ${opt}`).join('\n')}`;
        fullQuestion += `\n(default: ${defaultIndex + 1})`;
      }
      fullQuestion += '\n> ';

      this.rl.question(fullQuestion, (answer) => {
        if (options && options.length > 0) {
          const index = parseInt(answer.trim()) - 1;
          if (!isNaN(index) && index >= 0 && index < options.length) {
            resolve(options[index]);
            return;
          }
          if (answer.trim() === '') {
            resolve(options[defaultIndex]);
            return;
          }
          console.log('Invalid selection. Please choose a number from the list.');
          resolve(this.prompt(question, options, defaultIndex));
          return;
        }
        resolve(answer.trim() || '');
      });
    });
  }

  async run() {
    console.log('\n≡ƒôï Quick Setup - 5 Questions\n');

    // Question 1: Project type (simplified)
    const projectType = await this.prompt(
      '1∩╕ÅΓâú  What are you building?',
      [
        'Side Project / SaaS (web app)',
        'API / Backend Service',
        'Full-Stack App (frontend + backend)',
        'Static Website / Landing Page',
        'Other'
      ],
      0 // Default: Side Project
    );

    // Question 2: Primary language
    const language = await this.prompt(
      '\n2∩╕ÅΓâú  Primary language?',
      [
        'JavaScript',
        'TypeScript',
        'Python',
        'Other'
      ],
      1 // Default: TypeScript
    );

    // Question 3: Framework (context-aware based on project type)
    let frameworkOptions = [];
    if (projectType.includes('Side Project') || projectType.includes('Full-Stack')) {
      frameworkOptions = ['Next.js', 'React', 'Vue', 'Svelte', 'Vanilla JS'];
    } else if (projectType.includes('API')) {
      frameworkOptions = ['Express', 'Fastify', 'NestJS', 'None'];
    } else if (projectType.includes('Static')) {
      frameworkOptions = ['Astro', 'Next.js (static)', 'Vanilla HTML/CSS', 'None'];
    } else {
      frameworkOptions = ['Next.js', 'Express', 'React', 'None'];
    }

    const framework = await this.prompt(
      '\n3∩╕ÅΓâú  Framework?',
      frameworkOptions,
      0 // Default: first option
    );

    // Question 4: Features (simplified, auto-selected based on type)
    const features = [];
    if (projectType.includes('Side Project') || projectType.includes('Full-Stack')) {
      features.push('auth', 'database', 'api');
    } else if (projectType.includes('API')) {
      features.push('api', 'database');
    }

    const needsAuth = await this.prompt(
      '\n4∩╕ÅΓâú  Need authentication?',
      ['Yes', 'No'],
      projectType.includes('Side Project') ? 0 : 1
    );
    if (needsAuth === 'Yes' && !features.includes('auth')) {
      features.push('auth');
    }

    // Question 5: Package manager (auto-detect)
    let packageManager = 'npm';
    try {
      const lockFiles = await fs.readdir(process.cwd());
      if (lockFiles.includes('pnpm-lock.yaml')) {
        packageManager = 'pnpm';
      } else if (lockFiles.includes('yarn.lock')) {
        packageManager = 'yarn';
      } else if (lockFiles.includes('package-lock.json')) {
        packageManager = 'npm';
      }
    } catch (err) {
      // Default to npm
    }

    const confirmedPM = await this.prompt(
      `\n5∩╕ÅΓâú  Package manager? (detected: ${packageManager})`,
      ['npm', 'pnpm', 'yarn'],
      packageManager === 'npm' ? 0 : packageManager === 'pnpm' ? 1 : 2
    );

    // Generate manifest
    const manifest = {
      name: path.basename(process.cwd()),
      version: '1.0.0',
      productType: this.mapProductType(projectType),
      technologies: this.mapTechnologies(language, framework),
      features: features,
      packageManager: confirmedPM,
      deployment: {
        target: 'cloud-free-tier',
        platforms: this.suggestPlatforms(projectType, framework)
      },
      rationale: {
        productType: `Building a ${projectType.toLowerCase()}`,
        technologies: `Using ${language} with ${framework}`,
        features: features.length > 0 ? `Core features: ${features.join(', ')}` : 'Minimal feature set',
        deployment: 'Optimized for free-tier deployment (Vercel, Railway, Fly.io)'
      }
    };

    // Save manifest
    const manifestPath = path.join(process.cwd(), 'project.manifest.json');
    await fs.writeFile(manifestPath, JSON.stringify(manifest, null, 2));

    console.log(`\nΓ£à Created project.manifest.json`);
    console.log(`\n≡ƒôè Your Setup:`);
    console.log(`   Type: ${projectType}`);
    console.log(`   Language: ${language}`);
    console.log(`   Framework: ${framework}`);
    console.log(`   Features: ${features.length > 0 ? features.join(', ') : 'none'}`);
    console.log(`   Package Manager: ${confirmedPM}`);

    this.rl.close();
  }

  mapProductType(type) {
    if (type.includes('Side Project') || type.includes('SaaS')) return 'web-application';
    if (type.includes('API')) return 'api-service';
    if (type.includes('Full-Stack')) return 'full-stack-application';
    if (type.includes('Static')) return 'static-website';
    return 'other';
  }

  mapTechnologies(language, framework) {
    const tech = [];
    
    if (language === 'JavaScript') tech.push('javascript');
    if (language === 'TypeScript') tech.push('typescript', 'javascript');
    if (language === 'Python') tech.push('python');
    
    const frameworkLower = framework.toLowerCase();
    if (frameworkLower.includes('next')) tech.push('nextjs', 'react');
    else if (frameworkLower.includes('react')) tech.push('react');
    else if (frameworkLower.includes('vue')) tech.push('vue');
    else if (frameworkLower.includes('svelte')) tech.push('svelte');
    else if (frameworkLower.includes('express')) tech.push('express', 'nodejs');
    else if (frameworkLower.includes('fastify')) tech.push('fastify', 'nodejs');
    else if (frameworkLower.includes('nestjs')) tech.push('nestjs', 'nodejs');
    else if (frameworkLower.includes('astro')) tech.push('astro');
    
    if (tech.includes('express') || tech.includes('fastify') || tech.includes('nestjs') || tech.includes('nextjs')) {
      if (!tech.includes('nodejs')) tech.push('nodejs');
    }
    
    return tech;
  }

  suggestPlatforms(projectType, framework) {
    if (framework.includes('Next.js') || projectType.includes('Full-Stack')) {
      return ['vercel', 'netlify'];
    }
    if (projectType.includes('API')) {
      return ['railway', 'fly.io'];
    }
    if (projectType.includes('Static')) {
      return ['vercel', 'netlify', 'github-pages'];
    }
    return ['vercel', 'railway'];
  }
}

// CLI entry point
if (require.main === module) {
  const cli = new SimpleAgentCLI();
  cli.run().catch(err => {
    console.error('Error:', err.message);
    process.exit(1);
  });
}

module.exports = SimpleAgentCLI;

#!/usr/bin/env node

/**
 * Interactive CLI for guiding users through project setup
 * Generates project.manifest.json based on user selections
 */

import * as readline from 'readline';
import * as fs from 'fs';
import * as path from 'path';
import { createLogger } from '../utils/logger';
import { Requirements, ProjectManifest } from '../types/manifest';

const logger = createLogger({ context: 'agent-cli' });

export class AgentCLI {
  private rl: readline.Interface;

  constructor() {
    this.rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });
  }

  async prompt(question: string, options: string[] | null = null, defaultValue: number | string | null = null): Promise<string> {
    return new Promise((resolve) => {
      let fullQuestion = question;
      if (options && options.length > 0) {
        fullQuestion += `\n${options.map((opt, idx) => `${idx + 1}) ${opt}`).join('\n')}`;
        if (defaultValue !== null && typeof defaultValue === 'number') {
          fullQuestion += `\n(default: ${defaultValue + 1})`;
        }
      }
      fullQuestion += '\n> ';

      this.rl.question(fullQuestion, (answer: string) => {
        if (options && options.length > 0) {
          const index = parseInt(answer.trim()) - 1;
          if (!isNaN(index) && index >= 0 && index < options.length) {
            resolve(options[index]);
            return;
          }
          if (typeof defaultValue === 'number' && answer.trim() === '') {
            resolve(options[defaultValue]);
            return;
          }
          logger.warn('Invalid selection. Please choose a number from the list.');
          resolve(this.prompt(question, options, defaultValue));
          return;
        }
        resolve(answer.trim() || (typeof defaultValue === 'string' ? defaultValue : ''));
      });
    });
  }

  async promptYesNo(question: string, defaultValue: boolean = false): Promise<boolean> {
    const answer = await this.prompt(`${question} (y/n)`, null, defaultValue ? 'y' : 'n');
    const normalized = answer.toLowerCase();
    if (normalized === 'y' || normalized === 'yes') return true;
    if (normalized === 'n' || normalized === 'no') return false;
    logger.warn('Please answer y or n.');
    return this.promptYesNo(question, defaultValue);
  }

  async promptMultiSelect(question: string, options: string[], defaultValues: string[] = []): Promise<string[]> {
    logger.info(`${question}\nSelect multiple options (comma-separated numbers):`);
    options.forEach((opt, idx) => logger.info(`${idx + 1}) ${opt}`));
    logger.info(`(default: ${defaultValues.map(v => options.indexOf(v) + 1).join(',')})`);

    const defaultAnswer = defaultValues.map(v => options.indexOf(v) + 1).join(',');
    const answer = await this.prompt('', null, defaultAnswer);
    const indices = answer.split(',').map(s => parseInt(s.trim()) - 1);

    const selected: string[] = [];
    const invalid: number[] = [];
    indices.forEach(idx => {
      if (!isNaN(idx) && idx >= 0 && idx < options.length) {
        selected.push(options[idx]);
      } else {
        invalid.push(idx + 1);
      }
    });

    if (invalid.length > 0) {
      logger.warn(`Invalid selections: ${invalid.join(', ')}. Please try again.`);
      return this.promptMultiSelect(question, options, defaultValues);
    }

    return selected;
  }

  async collectRequirements(): Promise<Requirements> {
    logger.info('≡ƒÜÇ Welcome to the DevEnv Template Agent!');
    logger.info('I\'ll help you define your project requirements and generate a manifest.\n');

    // Product type
    const productTypes = [
      'Web Application',
      'API/Microservices',
      'Mobile App',
      'Desktop Application',
      'Library/SDK',
      'CLI Tool',
      'Other'
    ];
    const productType = await this.prompt('What type of product are you building?', productTypes, 0);

    // Core features
    const featureOptions = [
      'Authentication/Authorization',
      'REST API',
      'GraphQL API',
      'Web UI (Frontend)',
      'Database Integration',
      'Caching',
      'File Storage',
      'Real-time Features (WebSocket)',
      'Background Jobs/Queues',
      'Admin Panel',
      'API Documentation',
      'Monitoring/Logging',
      'Search Functionality',
      'Email/SMS Notifications'
    ];
    const coreFeatures = await this.promptMultiSelect(
      'Which core features does your product need?',
      featureOptions,
      [] // no defaults
    );

    // Tech stack preferences
    const stackOptions = [
      'Node.js',
      'Python',
      'Go',
      'C#/.NET',
      'Java',
      'Frontend (React/Vue/Angular)',
      'Full-stack (MERN/MEAN/etc.)',
      'Other'
    ];
    const preferredStack = await this.prompt('What\'s your preferred technology stack?', stackOptions, 0);

    // Deployment target
    const deploymentOptions = [
      'Cloud (AWS/GCP/Azure)',
      'Self-hosted (VPS/Dedicated)',
      'Docker Containers',
      'Kubernetes',
      'Serverless',
      'Static Hosting (Netlify/Vercel)',
      'Hybrid'
    ];
    const deploymentTarget = await this.prompt('What\'s your primary deployment target?', deploymentOptions, 2); // Docker default

    // Testing level
    const testingLevels = [
      'Unit tests only',
      'Unit + Integration tests',
      'Unit + Integration + E2E tests',
      'Comprehensive testing (including performance/load tests)',
      'Minimal testing (just enough to deploy)'
    ];
    const testingLevel = await this.prompt('What level of testing do you want?', testingLevels, 1);

    // Governance sensitivity
    const governanceOptions = [
      'Standard (basic security, some compliance)',
      'High (financial/healthcare data, strict compliance)',
      'Enterprise (audit trails, advanced security)',
      'Public sector (government standards)',
      'None (personal/hobby project)'
    ];
    const governanceSensitivity = await this.prompt('What governance/sensitivity level applies?', governanceOptions, 0);

    // Additional questions
    const needsCI = await this.promptYesNo('Do you need CI/CD pipeline setup?', true);
    const needsDocker = await this.promptYesNo('Do you need Docker configuration?', true);
    const needsMonitoring = await this.promptYesNo('Do you need monitoring/observability setup?', false);

    // Team size consideration
    const teamSizes = [
      'Solo developer',
      'Small team (2-5 developers)',
      'Medium team (6-15 developers)',
      'Large team (16+ developers)'
    ];
    const teamSize = await this.prompt('What\'s your team size?', teamSizes, 1);

    return {
      productType,
      coreFeatures,
      preferredStack,
      deploymentTarget,
      testingLevel,
      governanceSensitivity,
      needsCI,
      needsDocker,
      needsMonitoring,
      teamSize
    };
  }

  generateManifest(requirements: Requirements): ProjectManifest {
    // Derive features array for cleanup/scaffolding
    const features: string[] = [];

    // Map core features to cleanup features
    const featureMapping: Record<string, string[]> = {
      'Authentication/Authorization': ['auth'],
      'REST API': ['api'],
      'GraphQL API': ['graphql'],
      'Web UI (Frontend)': ['frontend'],
      'Database Integration': ['database'],
      'Caching': ['cache'],
      'File Storage': ['storage'],
      'Real-time Features (WebSocket)': ['websocket'],
      'Background Jobs/Queues': ['jobs'],
      'Admin Panel': ['admin'],
      'API Documentation': ['docs'],
      'Monitoring/Logging': ['monitoring'],
      'Search Functionality': ['search'],
      'Email/SMS Notifications': ['notifications']
    };

    requirements.coreFeatures.forEach(feature => {
      const mapped = featureMapping[feature];
      if (mapped) features.push(...mapped);
    });

    // Map stack to features
    const stackMapping: Record<string, string[]> = {
      'Node.js': ['node'],
      'Python': ['python'],
      'Go': ['go'],
      'C#/.NET': ['dotnet'],
      'Java': ['java'],
      'Frontend (React/Vue/Angular)': ['frontend'],
      'Full-stack (MERN/MEAN/etc.)': ['node', 'frontend']
    };
    const stackFeatures = stackMapping[requirements.preferredStack] || [];
    features.push(...stackFeatures);

    // Add infrastructure features
    if (requirements.needsCI) features.push('ci');
    if (requirements.needsDocker) features.push('docker');
    if (requirements.needsMonitoring) features.push('monitoring');

    // Map governance to features
    const governanceMapping: Record<string, string[]> = {
      'High (financial/healthcare data, strict compliance)': ['security', 'compliance'],
      'Enterprise (audit trails, advanced security)': ['security', 'audit', 'compliance'],
      'Public sector (government standards)': ['security', 'compliance', 'audit']
    };
    const govFeatures = governanceMapping[requirements.governanceSensitivity] || [];
    features.push(...govFeatures);

    // Map testing level
    const testingMapping: Record<string, string[]> = {
      'Unit tests only': ['unit-tests'],
      'Unit + Integration tests': ['unit-tests', 'integration-tests'],
      'Unit + Integration + E2E tests': ['unit-tests', 'integration-tests', 'e2e-tests'],
      'Comprehensive testing (including performance/load tests)': ['unit-tests', 'integration-tests', 'e2e-tests', 'performance-tests']
    };
    const testFeatures = testingMapping[requirements.testingLevel] || ['unit-tests'];
    features.push(...testFeatures);

    // Remove duplicates
    const uniqueFeatures = [...new Set(features)];

    return {
      version: '1.0.0',
      generatedAt: new Date().toISOString(),
      requirements,
      derived: {
        features: uniqueFeatures,
        rationale: {
          features: 'Features derived from your requirements to enable cleanup rules and scaffolding',
          stack: `Based on ${requirements.preferredStack} preference`,
          infrastructure: 'Based on deployment and operational needs',
          governance: 'Based on data sensitivity and compliance requirements',
          testing: 'Based on desired testing coverage level'
        }
      }
    };
  }

  async saveManifest(manifest: ProjectManifest, outputPath: string = 'project.manifest.json'): Promise<void> {
    try {
      fs.writeFileSync(outputPath, JSON.stringify(manifest, null, 2));
      logger.info(`\nΓ£à Manifest saved to ${outputPath}`);
      logger.info('\n≡ƒôï Summary of your selections:');
      logger.info(`   Product Type: ${manifest.requirements.productType}`);
      logger.info(`   Stack: ${manifest.requirements.preferredStack}`);
      logger.info(`   Features: ${manifest.requirements.coreFeatures.join(', ')}`);
      logger.info(`   Deployment: ${manifest.requirements.deploymentTarget}`);
      logger.info(`   Testing: ${manifest.requirements.testingLevel}`);
      logger.info(`   Governance: ${manifest.requirements.governanceSensitivity}`);
      logger.info(`\n≡ƒöº Derived features for cleanup/scaffolding: ${manifest.derived.features.join(', ')}`);
    } catch (error: any) {
      logger.error(`Γ¥î Failed to save manifest: ${error.message}`);
      process.exit(1);
    }
  }

  async run(): Promise<void> {
    try {
      const requirements = await this.collectRequirements();
      const manifest = this.generateManifest(requirements);
      await this.saveManifest(manifest);
      logger.info('\n≡ƒÄë Setup complete! Run `npm run agent:apply` to apply these settings to your project.');
    } catch (error: any) {
      logger.error(`Γ¥î Error: ${error.message}`);
      process.exit(1);
    } finally {
      this.rl.close();
    }
  }
}

// CLI entry point
if (require.main === module) {
  const cli = new AgentCLI();
  cli.run();
}

export default AgentCLI;

#!/usr/bin/env node

/**
 * Context Contract Questionnaire Generator
 *
 * Analyzes Context Contracts and generates targeted questions to fill gaps
 * before implementation begins.
 */

const fs = require('fs').promises;
const path = require('path');
const { Command } = require('commander');

class QuestionnaireGenerator {
  constructor() {
    this.rootDir = path.resolve(__dirname, '../..');
    this.questions = [];
    this.priorities = {
      critical: [],
      high: [],
      medium: [],
      low: []
    };
  }

  async run() {
    const program = new Command()
      .name('questionnaire')
      .description('Generate targeted questions for Context Contract completion')
      .requiredOption('-c, --ctx <file>', 'Context contract JSON file')
      .option('-o, --output <file>', 'Output file for updated context contract')
      .option('--interactive', 'Run in interactive mode to answer questions')
      .parse();

    const options = program.opts();

    try {
      console.log('Γ¥ô Context Contract Questionnaire\n');

      const contextContract = await this.loadContextContract(options.ctx);

      this.analyzeContract(contextContract);
      this.rankQuestions();
      this.displayQuestions();

      if (options.interactive) {
        await this.runInteractiveMode(contextContract, options.output || options.ctx);
      }

    } catch (error) {
      console.error('Γ¥î Questionnaire generation failed:', error.message);
      process.exit(1);
    }
  }

  async loadContextContract(filePath) {
    try {
      const fullPath = path.resolve(filePath);
      const content = await fs.readFile(fullPath, 'utf8');
      return JSON.parse(content);
    } catch (error) {
      throw new Error(`Failed to load context contract: ${error.message}`);
    }
  }

  analyzeContract(contract) {
    this.checkProblemDefinition(contract);
    this.checkGoalsAndScope(contract);
    this.checkConstraintsAndDependencies(contract);
    this.checkAssumptionsAndRisks(contract);
    this.checkAcceptanceCriteria(contract);
    this.checkImplementationReadiness(contract);
  }

  checkProblemDefinition(contract) {
    if (!contract.problem) {
      this.addQuestion({
        priority: 'critical',
        category: 'problem',
        question: 'What specific problem are you trying to solve?',
        field: 'problem.statement',
        help: 'Describe the current situation and why it needs to change'
      });
    } else {
      if (!contract.problem.context) {
        this.addQuestion({
          priority: 'high',
          category: 'problem',
          question: 'What is the broader context or background for this problem?',
          field: 'problem.context',
          help: 'Explain the history or circumstances that led to this problem'
        });
      }

      if (!contract.problem.impact) {
        this.addQuestion({
          priority: 'high',
          category: 'problem',
          question: 'What is the impact of not solving this problem?',
          field: 'problem.impact',
          help: 'Describe the business/user impact and consequences of inaction'
        });
      }

      if (!contract.problem.currentState) {
        this.addQuestion({
          priority: 'medium',
          category: 'problem',
          question: 'How does the current system/process work?',
          field: 'problem.currentState',
          help: 'Document the existing workflow or implementation'
        });
      }

      if (!contract.problem.desiredState) {
        this.addQuestion({
          priority: 'medium',
          category: 'problem',
          question: 'How should the system/process work after implementation?',
          field: 'problem.desiredState',
          help: 'Describe the target state and desired behavior'
        });
      }
    }
  }

  checkGoalsAndScope(contract) {
    if (!contract.goals || contract.goals.length === 0) {
      this.addQuestion({
        priority: 'critical',
        category: 'goals',
        question: 'What are the specific goals or outcomes you want to achieve?',
        field: 'goals',
        help: 'List measurable objectives and success criteria'
      });
    } else {
      for (const goal of contract.goals) {
        if (!goal.criteria) {
          this.addQuestion({
            priority: 'high',
            category: 'goals',
            question: `How will you measure success for: "${goal.description}"?`,
            field: `goals.${contract.goals.indexOf(goal)}.criteria`,
            help: 'Define specific, measurable success criteria'
          });
        }
      }
    }

    if (!contract.nonGoals || contract.nonGoals.length === 0) {
      this.addQuestion({
        priority: 'medium',
        category: 'scope',
        question: 'What is explicitly OUT OF SCOPE for this work?',
        field: 'nonGoals',
        help: 'Clearly define boundaries to prevent scope creep'
      });
    }
  }

  checkConstraintsAndDependencies(contract) {
    if (!contract.constraints || contract.constraints.length === 0) {
      this.addQuestion({
        priority: 'high',
        category: 'constraints',
        question: 'What technical, business, or operational constraints apply?',
        field: 'constraints',
        help: 'List limitations, requirements, or restrictions'
      });
    }

    if (!contract.dependencies || !contract.dependencies.external ||
        contract.dependencies.external.length === 0) {
      this.addQuestion({
        priority: 'medium',
        category: 'dependencies',
        question: 'What external systems, APIs, or services does this depend on?',
        field: 'dependencies.external',
        help: 'Identify dependencies that could affect implementation timeline'
      });
    }
  }

  checkAssumptionsAndRisks(contract) {
    if (!contract.assumptions || contract.assumptions.length === 0) {
      this.addQuestion({
        priority: 'high',
        category: 'assumptions',
        question: 'What assumptions are you making that could affect implementation?',
        field: 'assumptions',
        help: 'Document uncertainties that should be validated before starting'
      });
    }

    if (!contract.risks || contract.risks.length === 0) {
      this.addQuestion({
        priority: 'medium',
        category: 'risks',
        question: 'What are the potential risks or failure modes?',
        field: 'risks',
        help: 'Identify what could go wrong and mitigation strategies'
      });
    }

    if (!contract.unknowns || contract.unknowns.length === 0) {
      this.addQuestion({
        priority: 'low',
        category: 'unknowns',
        question: 'What questions or unknowns need to be investigated?',
        field: 'unknowns',
        help: 'List things you need to learn or validate before finalizing plans'
      });
    }
  }

  checkAcceptanceCriteria(contract) {
    if (!contract.acceptanceTests || contract.acceptanceTests.length === 0) {
      this.addQuestion({
        priority: 'critical',
        category: 'acceptance',
        question: 'How will you verify that the implementation meets requirements?',
        field: 'acceptanceTests',
        help: 'Define specific tests or criteria that must pass'
      });
    } else {
      for (const test of contract.acceptanceTests) {
        if (!test.criteria && !test.verification) {
          this.addQuestion({
            priority: 'high',
            category: 'acceptance',
            question: `How will you verify: "${test.description}"?`,
            field: `acceptanceTests.${contract.acceptanceTests.indexOf(test)}.verification`,
            help: 'Specify concrete verification methods or criteria'
          });
        }
      }
    }
  }

  checkImplementationReadiness(contract) {
    if (!contract.stakeholders || contract.stakeholders.length === 0) {
      this.addQuestion({
        priority: 'medium',
        category: 'stakeholders',
        question: 'Who are the stakeholders and what is their level of involvement?',
        field: 'stakeholders',
        help: 'Identify people who need to be informed or approve this work'
      });
    }

    if (!contract.metrics || contract.metrics.length === 0) {
      this.addQuestion({
        priority: 'low',
        category: 'metrics',
        question: 'How will you measure the success or impact of this change?',
        field: 'metrics',
        help: 'Define success metrics and baseline measurements'
      });
    }
  }

  addQuestion(question) {
    this.questions.push({
      id: `q${this.questions.length + 1}`,
      ...question
    });
  }

  rankQuestions() {
    for (const question of this.questions) {
      this.priorities[question.priority].push(question);
    }
  }

  displayQuestions() {
    console.log('≡ƒôï GENERATED QUESTIONS\n');

    const priorities = ['critical', 'high', 'medium', 'low'];

    for (const priority of priorities) {
      const questions = this.priorities[priority];
      if (questions.length > 0) {
        console.log(`${priority.toUpperCase()} PRIORITY:`);
        for (const question of questions) {
          console.log(`  ${question.id}. ${question.question}`);
          console.log(`     ≡ƒÆí ${question.help}`);
          console.log(`     ≡ƒôì Field: ${question.field}`);
          console.log();
        }
      }
    }

    console.log(`≡ƒôè Total: ${this.questions.length} questions generated`);
    console.log(`   Critical: ${this.priorities.critical.length}`);
    console.log(`   High: ${this.priorities.high.length}`);
    console.log(`   Medium: ${this.priorities.medium.length}`);
    console.log(`   Low: ${this.priorities.low.length}`);
    console.log();
  }

  async runInteractiveMode(contract, outputPath) {
    const readline = require('readline');
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    console.log('≡ƒñû INTERACTIVE MODE\n');
    console.log('Answer the questions below to complete your context contract.');
    console.log('Press Enter to skip a question, or type your answer.\n');

    for (const priority of ['critical', 'high', 'medium', 'low']) {
      for (const question of this.priorities[priority]) {
        const answer = await this.askQuestion(rl, question);
        if (answer) {
          this.updateContract(contract, question.field, answer);
        }
      }
    }

    rl.close();

    // Save updated contract
    await fs.writeFile(outputPath, JSON.stringify(contract, null, 2));
    console.log(`\n≡ƒÆ╛ Updated context contract saved to: ${outputPath}`);
  }

  askQuestion(rl, question) {
    return new Promise((resolve) => {
      rl.question(`${question.question}\n> `, (answer) => {
        resolve(answer.trim());
      });
    });
  }

  updateContract(contract, fieldPath, value) {
    const parts = fieldPath.split('.');
    let current = contract;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      if (!current[part]) {
        current[part] = {};
      }
      current = current[part];
    }

    const lastPart = parts[parts.length - 1];
    if (Array.isArray(current[lastPart])) {
      current[lastPart].push(value);
    } else {
      current[lastPart] = value;
    }
  }
}

// Run the questionnaire generator
if (require.main === module) {
  const generator = new QuestionnaireGenerator();
  generator.run().catch(error => {
    console.error('≡ƒÆÑ Unhandled error:', error);
    process.exit(1);
  });
}

module.exports = QuestionnaireGenerator;

#!/usr/bin/env node

/**
 * Template Cleanup Engine
 *
 * Stack-agnostic engine for removing template-only code after scaffolding.
 * Processes declarative rules from YAML config to clean files, blocks, lines, and dependencies.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { glob } from 'glob';
import yaml from 'yaml';
import os from 'os';
import { resolveConfigPath } from '../utils/path-resolver';
import { getPackageManager } from './package-managers';
import { CleanupRule, CleanupAction, CleanupReport, CleanupConfig } from '../types/cleanup';
import { PerformanceTracker } from '../types/performance';
import { FileCache, ConfigCache } from '../utils/cache';
import { parallel, calculateOptimalConcurrency } from '../utils/parallel';
import { ProgressTracker, ProgressVerbosity } from '../utils/progress';

// Default file extensions for code files (used by block/line marker rules)
const CODE_EXTENSIONS = [
  "**/*.js",
  "**/*.ts",
  "**/*.jsx",
  "**/*.tsx",
  "**/*.py",
  "**/*.rb",
  "**/*.go",
  "**/*.rs",
  "**/*.java",
  "**/*.cs",
  "**/*.cpp",
  "**/*.c",
  "**/*.h",
  "**/*.php",
  "**/*.scala",
  "**/*.kt",
  "**/*.swift",
  "**/*.dart",
  "**/*.sh",
  "**/*.bash",
  "**/*.zsh",
  "**/*.ps1",
  "**/*.sql",
  "**/*.html",
  "**/*.xml",
];

interface CleanupEngineOptions {
  profile?: string;
  features?: string[];
  configPath?: string;
  workingDir?: string;
  dryRun?: boolean;
  failOnActions?: boolean;
  onlyRules?: string[];
  excludeRules?: string[];
  excludeGlobs?: string[];
  keepFiles?: string[];
  report?: string;
  performance?: boolean;
  cache?: boolean;
  parallel?: boolean;
  concurrency?: number;
  progress?: boolean;
  progressVerbosity?: 'silent' | 'simple' | 'detailed';
  jsonProgress?: boolean;
}

interface CommentSyntax {
  single: string | null;
  block: { start: string; end: string } | null;
}

interface BlockInfo {
  type: string;
  start: number;
  end: number;
  marker: MarkerConfig;
}

interface MarkerConfig {
  start: string;
  end: string;
}

interface ParsedContent {
  blocks: BlockInfo[];
  taggedLines: number[];
}

type RuleHandler = (rule: CleanupRule) => Promise<CleanupAction[]>;

/**
 * Main cleanup engine class
 */
export class CleanupEngine {
  private config: CleanupConfig | null = null;
  private profile: string;
  private features: Set<string>;
  private configPath: string;
  private workingDir: string;
  private dryRun: boolean;
  private failOnActions: boolean;
  private onlyRules: Set<string> | null;
  private excludeRules: Set<string> | null;
  private excludeGlobs: string[];
  private keepFiles: Set<string> | null;
  private excludeGlobCache: Map<string, string[]>;
  private report: CleanupReport;
  private performanceEnabled: boolean;
  private performanceTracker: PerformanceTracker | null;
  private cacheEnabled: boolean;
  private fileCache: FileCache | null;
  private configCache: ConfigCache | null;
  private parallelEnabled: boolean;
  private concurrency: number;
  private progressEnabled: boolean;
  private progressTracker: ProgressTracker | null;

  constructor(options: CleanupEngineOptions = {}) {
    this.profile = options.profile || "common";
    this.features = new Set(options.features || []);
    this.configPath = options.configPath || "cleanup.config.yaml";
    this.workingDir = options.workingDir || process.cwd();
    this.dryRun = options.dryRun !== false; // default true for safety
    this.failOnActions = options.failOnActions || false;

    // Rule filtering options
    this.onlyRules = options.onlyRules ? new Set(options.onlyRules) : null;
    this.excludeRules = options.excludeRules ? new Set(options.excludeRules) : null;
    this.excludeGlobs = options.excludeGlobs || [];
    this.keepFiles = options.keepFiles
      ? new Set(options.keepFiles.map(f => path.resolve(this.workingDir, f)))
      : null;

    // Performance tracking
    this.performanceEnabled = options.performance || false;
    this.performanceTracker = this.performanceEnabled ? new PerformanceTracker() : null;

    // Caching
    this.cacheEnabled = options.cache !== false; // enabled by default
    this.fileCache = this.cacheEnabled ? new FileCache() : null;
    this.configCache = this.cacheEnabled ? new ConfigCache() : null;

    // Parallel processing
    this.parallelEnabled = options.parallel || false;
    const cpuCount = os.cpus().length;
    this.concurrency = options.concurrency || cpuCount;

    // Progress tracking
    this.progressEnabled = options.progress || false;
    this.progressTracker = this.progressEnabled
      ? new ProgressTracker(
          options.progressVerbosity || 'simple',
          options.jsonProgress || false
        )
      : null;

    // Performance optimizations
    this.excludeGlobCache = new Map();

    this.report = {
      timestamp: new Date().toISOString(),
      profile: this.profile,
      features: Array.from(this.features),
      dryRun: this.dryRun,
      actions: [],
      errors: [],
      summary: {
        totalActions: 0,
        filesDeleted: 0,
        linesRemoved: 0,
        blocksRemoved: 0,
        dependenciesRemoved: 0,
      },
    };
  }

  /**
   * Load and validate configuration
   */
  async loadConfig(): Promise<CleanupConfig> {
    try {
      const configPath = resolveConfigPath(this.configPath, this.workingDir);

      // Load file content
      const configContent = await fs.readFile(configPath, "utf8");

      // Try to get from cache first
      let parsedConfig: CleanupConfig;
      let configCached = false;

      if (this.configCache && this.fileCache) {
        const contentHash = this.fileCache.generateHash(configContent);
        const cached = this.configCache.get(configPath, contentHash);
        if (cached) {
          parsedConfig = cached;
          configCached = true;
        } else {
          // Parse and cache the config
          parsedConfig = yaml.parse(configContent) as CleanupConfig;
          this.configCache.set(configPath, parsedConfig, contentHash);
        }
      } else {
        // No caching, just parse
        parsedConfig = yaml.parse(configContent) as CleanupConfig;
      }

      // Track cache hit/miss in performance tracker
      if (this.performanceTracker) {
        this.performanceTracker.trackFileScanned();
      }

      // Validate config structure
      if (!parsedConfig.profiles || !parsedConfig.profiles[this.profile]) {
        throw new Error(`Profile '${this.profile}' not found in config`);
      }

      // Set defaults
      parsedConfig.comment_syntax = parsedConfig.comment_syntax || {};
      parsedConfig.markers = parsedConfig.markers || {};

      // Merge default features
      if (parsedConfig.features) {
        parsedConfig.features.forEach(f => this.features.add(f));
      }

      // Store the validated config
      this.config = parsedConfig;
      return this.config;
    } catch (error: any) {
      throw new Error(`Failed to load config from ${this.configPath}: ${error.message}`);
    }
  }

  /**
   * Get resolved rules for current profile, handling extends and conditionals
   */
  getRules(): CleanupRule[] {
    if (!this.config) {
      throw new Error('Config not loaded. Call loadConfig() first.');
    }

    const rules: CleanupRule[] = [];

    // Handle extends (recursive)
    const collectRules = (profileName: string): void => {
      const prof = this.config!.profiles[profileName];
      if (!prof) return;

      if (prof.extends) {
        collectRules(prof.extends);
      }

      if (prof.rules) {
        rules.push(...prof.rules);
      }
    };

    collectRules(this.profile);

    // Add conditional rules - they are evaluated based on their individual conditions
    if (this.config.conditional_rules) {
      for (const conditionalRules of Object.values(this.config.conditional_rules)) {
        rules.push(...conditionalRules);
      }
    }

    return rules;
  }

  /**
   * Execute all rules
   */
  async execute(): Promise<CleanupReport> {
    // Start performance tracking
    if (this.performanceTracker) {
      this.performanceTracker.start();
      this.performanceTracker.setParallelMode(this.parallelEnabled, this.concurrency);
    }

    const rules = this.getRules();

    // Create overall progress bar
    if (this.progressTracker) {
      this.progressTracker.createBar('overall', {
        total: rules.length,
        label: 'Cleanup Progress',
      });
    }

    for (let i = 0; i < rules.length; i++) {
      const rule = rules[i];
      try {
        await this.executeRule(rule);

        // Update overall progress
        if (this.progressTracker) {
          this.progressTracker.updateBar('overall', i + 1);
        }
      } catch (error: any) {
        this.report.errors.push({
          rule: rule.id,
          error: error.message,
          stack: error.stack,
        });

        // Track error in performance metrics
        if (this.performanceTracker) {
          this.performanceTracker.trackRuleExecution(rule.id, 0, 0, true);
        }
      }
    }

    // Calculate summary
    this.calculateSummary();

    // Finish overall progress bar
    if (this.progressTracker) {
      this.progressTracker.finishBar('overall');
    }

    // End performance tracking and print report
    if (this.performanceTracker) {
      this.performanceTracker.end();
      this.performanceTracker.printReport();
    }

    return this.report;
  }

  /**
   * Check if a rule should be executed based on only/exclude filters
   */
  private shouldExecuteRule(rule: CleanupRule): boolean {
    // If onlyRules is specified, only include rules in that set
    if (this.onlyRules && !this.onlyRules.has(rule.id)) {
      return false;
    }

    // If excludeRules is specified, exclude rules in that set
    if (this.excludeRules && this.excludeRules.has(rule.id)) {
      return false;
    }

    return true;
  }

  /**
   * Check if a file should be processed (not excluded by globs or keep list)
   */
  private shouldProcessFile(filePath: string): boolean {
    const absolutePath = path.resolve(this.workingDir, filePath);
    // Normalize path for cross-platform compatibility (Windows case-insensitive)
    const normalizedPath = this.normalizePath(absolutePath);

    // Check keep files (normalized absolute paths)
    if (this.keepFiles) {
      for (const keepPath of this.keepFiles) {
        if (normalizedPath === this.normalizePath(keepPath)) {
          return false;
        }
      }
    }

    // Check exclude globs (with caching for performance)
    for (const pattern of this.excludeGlobs) {
      let matches = this.excludeGlobCache.get(pattern);
      if (!matches) {
        matches = glob.sync(pattern, {
          cwd: this.workingDir,
          absolute: true,
        });
        this.excludeGlobCache.set(pattern, matches);
      }
      if (matches.some(match => normalizedPath.startsWith(this.normalizePath(match)))) {
        return false;
      }
    }

    return true;
  }

  /**
   * Normalize path for cross-platform compatibility
   */
  private normalizePath(filePath: string): string {
    // Convert to forward slashes and normalize case on Windows
    let normalized = path.normalize(filePath).replace(/\\/g, "/");
    if (process.platform === "win32") {
      normalized = normalized.toLowerCase();
    }
    return normalized;
  }

  /**
   * Execute a single rule
   */
  private async executeRule(rule: CleanupRule): Promise<void> {
    // Check rule filtering
    if (!this.shouldExecuteRule(rule)) {
      return;
    }

    const ruleType = rule.type;
    const handler = this.getRuleHandler(ruleType);

    if (!handler) {
      throw new Error(`Unknown rule type: ${ruleType}`);
    }

    // Time rule execution
    const startTime = this.performanceTracker ? Date.now() : 0;

    const actions = await handler(rule);
    if (actions && actions.length > 0) {
      this.report.actions.push(...actions);
    }

    // Track rule execution time
    if (this.performanceTracker) {
      const duration = Date.now() - startTime;
      this.performanceTracker.trackRuleExecution(rule.id, duration, actions?.length || 0, false);
    }
  }

  /**
   * Get handler function for rule type
   */
  private getRuleHandler(type: string): RuleHandler | null {
    const handlers: Record<string, RuleHandler> = {
      file_glob_delete: this.handleFileGlobDelete.bind(this),
      block_markers: this.handleBlockMarkers.bind(this),
      line_tag: this.handleLineTag.bind(this),
      conditional_block: this.handleConditionalBlock.bind(this),
      prune_empty: this.handlePruneEmpty.bind(this),
      package_prune: this.handlePackagePrune.bind(this),
      custom: this.handleCustomRule.bind(this),
    };

    return handlers[type] || null;
  }

  /**
   * Get comment syntax for file extension
   */
  private getCommentSyntax(filePath: string): CommentSyntax {
    if (!this.config) {
      return { single: "//", block: null };
    }

    const ext = path.extname(filePath).toLowerCase();
    const syntax = this.config.comment_syntax[ext];

    if (!syntax) {
      // Default to single-line comment
      return { single: "//", block: null };
    }

    if (typeof syntax === "string") {
      return { single: syntax, block: null };
    }

    if (Array.isArray(syntax) && syntax.length === 2) {
      return { single: null, block: { start: syntax[0], end: syntax[1] } };
    }

    return { single: "//", block: null };
  }

  /**
   * Detect if line contains a marker
   */
  private detectMarker(line: string, marker: string, commentSyntax: CommentSyntax): boolean {
    const trimmed = line.trim();

    // Check single-line comments
    if (commentSyntax.single && trimmed.startsWith(commentSyntax.single)) {
      const comment = trimmed.slice(commentSyntax.single.length).trim();
      return comment.includes(marker);
    }

    // Check block comments
    if (commentSyntax.block) {
      const { start, end } = commentSyntax.block;
      if (trimmed.includes(start) && trimmed.includes(end)) {
        const startIdx = trimmed.indexOf(start);
        const endIdx = trimmed.indexOf(end, startIdx + start.length);
        if (startIdx !== -1 && endIdx !== -1) {
          const comment = trimmed.slice(startIdx + start.length, endIdx).trim();
          return comment.includes(marker);
        }
      }
    }

    return false;
  }

  /**
   * Parse file content for template markers
   */
  private parseFileContent(content: string, filePath: string): ParsedContent {
    if (!this.config) {
      return { blocks: [], taggedLines: [] };
    }

    const lines = content.split("\n");
    const commentSyntax = this.getCommentSyntax(filePath);
    const blocks: BlockInfo[] = [];
    const taggedLines: number[] = [];

    let inBlock = false;
    let blockStart = -1;
    let blockType: string | null = null;
    let blockMarker: MarkerConfig | null = null;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmed = line.trim();

      // Check for line tags
      if (this.config.markers.line_tag) {
        const lineTag = typeof this.config.markers.line_tag === 'string' 
          ? this.config.markers.line_tag 
          : (this.config.markers.line_tag as any).start;
        if (trimmed.includes(lineTag)) {
          taggedLines.push(i);
          continue;
        }
      }

      // Check for block markers
      if (!inBlock) {
        // Look for start markers
        for (const [type, markerConfig] of Object.entries(this.config.markers)) {
          if (type === "line_tag") continue;

          const config = markerConfig as MarkerConfig;
          if (this.detectMarker(line, config.start, commentSyntax)) {
            inBlock = true;
            blockStart = i;
            blockType = type;
            blockMarker = config;
            break;
          }
        }
      } else {
        // Look for end marker
        if (blockMarker && this.detectMarker(line, blockMarker.end, commentSyntax)) {
          blocks.push({
            type: blockType!,
            start: blockStart,
            end: i,
            marker: blockMarker,
          });
          inBlock = false;
          blockStart = -1;
          blockType = null;
          blockMarker = null;
        }
      }
    }

    return { blocks, taggedLines };
  }

  /**
   * Handle file glob delete rule
   */
  private async handleFileGlobDelete(rule: CleanupRule): Promise<CleanupAction[]> {
    const actions: CleanupAction[] = [];
    const globs = Array.isArray(rule.glob) ? rule.glob : [rule.glob];
    const exclude = [...(rule.exclude || []), ...this.excludeGlobs];

    for (const pattern of globs) {
      if (!pattern) continue;

      const files = await glob(pattern, {
        cwd: this.workingDir,
        absolute: true,
        ignore: exclude,
      });

      // Filter files first
      const filesToProcess = files.filter(file => {
        const relativePath = path.relative(this.workingDir, file);
        return this.shouldProcessFile(relativePath);
      });

      if (this.parallelEnabled && filesToProcess.length > 10) {
        // Create per-rule progress bar in detailed mode
        if (this.progressTracker && this.progressEnabled) {
          this.progressTracker.createBar(rule.id, {
            total: filesToProcess.length,
            label: `${rule.id} (files)`,
          });
        }

        // Use parallel processing for large file sets
        const result = await parallel(
          filesToProcess,
          async (file) => {
            const relativePath = path.relative(this.workingDir, file);

            if (!this.dryRun) {
              await fs.rm(file, { recursive: true, force: true });
            }

            return {
              type: "file_delete",
              rule: rule.id,
              path: relativePath,
              dryRun: this.dryRun,
            } as CleanupAction;
          },
          { 
            concurrency: this.concurrency,
            onProgress: (completed, total) => {
              if (this.progressTracker) {
                this.progressTracker.updateBar(rule.id, completed);
              }
            }
          }
        );

        // Finish per-rule progress bar
        if (this.progressTracker) {
          this.progressTracker.finishBar(rule.id);
        }

        actions.push(...result.results.filter(r => r !== undefined));

        // Track batch in performance metrics
        if (this.performanceTracker) {
          this.performanceTracker.trackBatch();
        }
      } else {
        // Sequential processing for small file sets
        for (const file of filesToProcess) {
          const relativePath = path.relative(this.workingDir, file);

          if (!this.dryRun) {
            await fs.rm(file, { recursive: true, force: true });
          }

          actions.push({
            type: "file_delete",
            rule: rule.id,
            path: relativePath,
            dryRun: this.dryRun,
          });
        }
      }
    }

    return actions;
  }

  /**
   * Handle block markers rule
   */
  private async handleBlockMarkers(rule: CleanupRule): Promise<CleanupAction[]> {
    const actions: CleanupAction[] = [];
    const globs = rule.include_globs || CODE_EXTENSIONS;
    const excludeGlobs = [...(rule.exclude_globs || []), ...this.excludeGlobs];

    for (const pattern of globs) {
      const files = await glob(pattern, {
        cwd: this.workingDir,
        absolute: true,
        ignore: excludeGlobs,
        nodir: true,
      });

      // Filter files first
      const filesToProcess = files.filter(file => {
        const relativePath = path.relative(this.workingDir, file);
        return this.shouldProcessFile(relativePath);
      });

      if (this.parallelEnabled && filesToProcess.length > 10) {
        // Create per-rule progress bar in detailed mode
        if (this.progressTracker && this.progressEnabled) {
          this.progressTracker.createBar(rule.id, {
            total: filesToProcess.length,
            label: `${rule.id} (blocks)`,
          });
        }

        // Use parallel processing for large file sets
        const result = await parallel(
          filesToProcess,
          async (file) => {
            try {
              const content = await fs.readFile(file, "utf8");
              const { blocks } = this.parseFileContent(content, file);

              const templateBlocks = blocks.filter(b => b.type === "template_only");

              if (templateBlocks.length > 0) {
                let newContent = content;
                const lines = newContent.split("\n");

                // Remove blocks in reverse order to maintain line numbers
                templateBlocks.reverse().forEach(block => {
                  lines.splice(block.start, block.end - block.start + 1);
                });

                newContent = lines.join("\n");

                if (!this.dryRun) {
                  await fs.writeFile(file, newContent);
                }

                return {
                  type: "block_remove",
                  rule: rule.id,
                  path: path.relative(this.workingDir, file),
                  blocksRemoved: templateBlocks.length,
                  dryRun: this.dryRun,
                } as CleanupAction;
              }
            } catch (error: any) {
              this.report.errors.push({
                rule: rule.id,
                file: path.relative(this.workingDir, file),
                error: `Failed to process file: ${error.message}`,
              });
            }
            return undefined;
          },
          { 
            concurrency: this.concurrency,
            onProgress: (completed, total) => {
              if (this.progressTracker) {
                this.progressTracker.updateBar(rule.id, completed);
              }
            }
          }
        );

        // Finish per-rule progress bar
        if (this.progressTracker) {
          this.progressTracker.finishBar(rule.id);
        }

        actions.push(...result.results.filter(r => r !== undefined));

        // Track batch in performance metrics
        if (this.performanceTracker) {
          this.performanceTracker.trackBatch();
        }
      } else {
        // Sequential processing for small file sets
        for (const file of filesToProcess) {
          const relativePath = path.relative(this.workingDir, file);

          try {
            const content = await fs.readFile(file, "utf8");
            const { blocks } = this.parseFileContent(content, file);

            const templateBlocks = blocks.filter(b => b.type === "template_only");

            if (templateBlocks.length > 0) {
              let newContent = content;
              const lines = newContent.split("\n");

              // Remove blocks in reverse order to maintain line numbers
              templateBlocks.reverse().forEach(block => {
                lines.splice(block.start, block.end - block.start + 1);
              });

              newContent = lines.join("\n");

              if (!this.dryRun) {
                await fs.writeFile(file, newContent);
              }

              actions.push({
                type: "block_remove",
                rule: rule.id,
                path: path.relative(this.workingDir, file),
                blocksRemoved: templateBlocks.length,
                dryRun: this.dryRun,
              });
            }
          } catch (error: any) {
            this.report.errors.push({
              rule: rule.id,
              file: path.relative(this.workingDir, file),
              error: `Failed to process file: ${error.message}`,
            });
          }
        }
      }
    }

    return actions;
  }

  /**
   * Handle line tag rule
   */
  private async handleLineTag(rule: CleanupRule): Promise<CleanupAction[]> {
    const actions: CleanupAction[] = [];
    const globs = rule.include_globs || CODE_EXTENSIONS;
    const excludeGlobs = [...(rule.exclude_globs || []), ...this.excludeGlobs];

    for (const pattern of globs) {
      const files = await glob(pattern, {
        cwd: this.workingDir,
        absolute: true,
        ignore: excludeGlobs,
        nodir: true,
      });

      // Filter files first
      const filesToProcess = files.filter(file => {
        const relativePath = path.relative(this.workingDir, file);
        return this.shouldProcessFile(relativePath);
      });

      if (this.parallelEnabled && filesToProcess.length > 10) {
        // Create per-rule progress bar in detailed mode
        if (this.progressTracker && this.progressEnabled) {
          this.progressTracker.createBar(rule.id, {
            total: filesToProcess.length,
            label: `${rule.id} (lines)`,
          });
        }

        // Use parallel processing for large file sets
        const result = await parallel(
          filesToProcess,
          async (file) => {
            try {
              const content = await fs.readFile(file, "utf8");
              const lines = content.split("\n");
              const { taggedLines } = this.parseFileContent(content, file);

              if (taggedLines.length > 0) {
                // Remove tagged lines in reverse order
                taggedLines.reverse().forEach(lineIndex => {
                  lines.splice(lineIndex, 1);
                });

                const newContent = lines.join("\n");

                if (!this.dryRun) {
                  await fs.writeFile(file, newContent);
                }

                return {
                  type: "line_remove",
                  rule: rule.id,
                  path: path.relative(this.workingDir, file),
                  linesRemoved: taggedLines.length,
                  dryRun: this.dryRun,
                } as CleanupAction;
              }
            } catch (error: any) {
              this.report.errors.push({
                rule: rule.id,
                file: path.relative(this.workingDir, file),
                error: `Failed to process file: ${error.message}`,
              });
            }
            return undefined;
          },
          { 
            concurrency: this.concurrency,
            onProgress: (completed, total) => {
              if (this.progressTracker) {
                this.progressTracker.updateBar(rule.id, completed);
              }
            }
          }
        );

        // Finish per-rule progress bar
        if (this.progressTracker) {
          this.progressTracker.finishBar(rule.id);
        }

        actions.push(...result.results.filter(r => r !== undefined));

        // Track batch in performance metrics
        if (this.performanceTracker) {
          this.performanceTracker.trackBatch();
        }
      } else {
        // Sequential processing for small file sets
        for (const file of filesToProcess) {
          const relativePath = path.relative(this.workingDir, file);

          try {
            const content = await fs.readFile(file, "utf8");
            const lines = content.split("\n");
            const { taggedLines } = this.parseFileContent(content, file);

            if (taggedLines.length > 0) {
              // Remove tagged lines in reverse order
              taggedLines.reverse().forEach(lineIndex => {
                lines.splice(lineIndex, 1);
              });

              const newContent = lines.join("\n");

              if (!this.dryRun) {
                await fs.writeFile(file, newContent);
              }

              actions.push({
                type: "line_remove",
                rule: rule.id,
                path: path.relative(this.workingDir, file),
                linesRemoved: taggedLines.length,
                dryRun: this.dryRun,
              });
            }
          } catch (error: any) {
            this.report.errors.push({
              rule: rule.id,
              file: path.relative(this.workingDir, file),
              error: `Failed to process file: ${error.message}`,
            });
          }
        }
      }
    }

    return actions;
  }

  /**
   * Handle conditional block rule
   */
  private async handleConditionalBlock(rule: CleanupRule): Promise<CleanupAction[]> {
    const actions: CleanupAction[] = [];
    const condition = rule.condition;
    const shouldRemove = this.evaluateCondition(condition);

    if (!shouldRemove) {
      return actions; // Keep the blocks
    }

    const globs = rule.include_globs || ["**/*"];
    const excludeGlobs = [...(rule.exclude_globs || []), ...this.excludeGlobs];

    for (const pattern of globs) {
      const files = await glob(pattern, {
        cwd: this.workingDir,
        absolute: true,
        ignore: excludeGlobs,
        nodir: true,
      });

      for (const file of files) {
        const relativePath = path.relative(this.workingDir, file);

        // Check file filtering
        if (!this.shouldProcessFile(relativePath)) {
          continue;
        }
        try {
          const content = await fs.readFile(file, "utf8");
          const { blocks } = this.parseFileContent(content, file);

          const conditionalBlocks = blocks.filter(b => b.type === "conditional");

          if (conditionalBlocks.length > 0) {
            let newContent = content;
            const lines = newContent.split("\n");

            // Remove blocks in reverse order
            conditionalBlocks.reverse().forEach(block => {
              lines.splice(block.start, block.end - block.start + 1);
            });

            newContent = lines.join("\n");

            if (!this.dryRun) {
              await fs.writeFile(file, newContent);
            }

            actions.push({
              type: "block_remove",
              rule: rule.id,
              path: path.relative(this.workingDir, file),
              blocksRemoved: conditionalBlocks.length,
              condition: condition,
              dryRun: this.dryRun,
            });
          }
        } catch (error: any) {
          this.report.errors.push({
            rule: rule.id,
            file: path.relative(this.workingDir, file),
            error: `Failed to process file: ${error.message}`,
          });
        }
      }
    }

    return actions;
  }

  /**
   * Evaluate conditional expression
   */
  private evaluateCondition(condition: string | undefined): boolean {
    if (!condition) return false;

    // Simple feature-based conditions: "feature" or "!feature"
    if (condition.startsWith("!")) {
      const feature = condition.slice(1);
      return !this.features.has(feature);
    } else {
      return this.features.has(condition);
    }
  }

  /**
   * Handle prune empty rule
   */
  private async handlePruneEmpty(rule: CleanupRule): Promise<CleanupAction[]> {
    const actions: CleanupAction[] = [];
    const removeEmptyFiles = rule.remove_empty_files !== false;
    const removeEmptyDirs = rule.remove_empty_dirs !== false;

    // Collect all files and directories
    const allFiles = await glob("**/*", {
      cwd: this.workingDir,
      absolute: true,
    });

    const files: string[] = [];
    const dirs: string[] = [];

    for (const file of allFiles) {
      try {
        const stat = await fs.stat(file);
        if (stat.isDirectory()) {
          dirs.push(file);
        } else {
          files.push(file);
        }
      } catch (error) {
        // Skip files that can't be accessed
      }
    }

    dirs.reverse(); // Process subdirs first

    // Remove empty files
    if (removeEmptyFiles) {
      for (const file of files) {
        try {
          const content = await fs.readFile(file, "utf8");
          if (content.trim() === "") {
            if (!this.dryRun) {
              await fs.unlink(file);
            }
            actions.push({
              type: "file_delete",
              rule: rule.id,
              path: path.relative(this.workingDir, file),
              reason: "empty file",
              dryRun: this.dryRun,
            });
          }
        } catch (error) {
          // File might not exist or be readable, skip
        }
      }
    }

    // Remove empty directories
    if (removeEmptyDirs) {
      for (const dir of dirs) {
        try {
          const contents = await fs.readdir(dir);
          if (contents.length === 0) {
            if (!this.dryRun) {
              await fs.rmdir(dir);
            }
            actions.push({
              type: "file_delete",
              rule: rule.id,
              path: path.relative(this.workingDir, dir),
              reason: "empty directory",
              dryRun: this.dryRun,
            });
          }
        } catch (error) {
          // Directory might not exist or be readable, skip
        }
      }
    }

    return actions;
  }

  /**
   * Handle package prune rule
   */
  private async handlePackagePrune(rule: CleanupRule): Promise<CleanupAction[]> {
    const actions: CleanupAction[] = [];
    const managerName = rule.package_prune?.manager || "npm";

    try {
      const packageManager = getPackageManager(managerName, this.workingDir, this.dryRun);
      const result = await packageManager.prune(rule);

      if (result && result.actions) {
        actions.push(...result.actions);
      }
    } catch (error: any) {
      this.report.errors.push({
        rule: rule.id,
        error: `Package pruning failed: ${error.message}`,
      });
    }

    return actions;
  }


  /**
   * Handle custom rule
   */
  private async handleCustomRule(rule: CleanupRule): Promise<CleanupAction[]> {
    const actions: CleanupAction[] = [];

    if (!rule.module) {
      throw new Error(`Custom rule '${rule.id}' must specify a 'module' path`);
    }

    try {
      // Resolve module path relative to working directory
      const modulePath = path.resolve(this.workingDir, rule.module);

      // Load the custom module
      const customModule = require(modulePath);

      if (typeof customModule.execute !== "function") {
        throw new Error(`Custom module '${rule.module}' must export an 'execute' function`);
      }

      // Execute the custom rule
      const result = await customModule.execute(rule, this);

      // Handle different return formats
      if (result && Array.isArray(result)) {
        actions.push(...result);
      } else if (result && result.actions && Array.isArray(result.actions)) {
        actions.push(...result.actions);
      }
    } catch (error: any) {
      throw new Error(`Failed to execute custom rule '${rule.id}': ${error.message}`);
    }

    return actions;
  }

  /**
   * Calculate summary statistics
   */
  private calculateSummary(): void {
    const summary = {
      totalActions: this.report.actions.length,
      filesDeleted: 0,
      linesRemoved: 0,
      blocksRemoved: 0,
      dependenciesRemoved: 0,
    };

    for (const action of this.report.actions) {
      switch (action.type) {
        case "file_delete":
          summary.filesDeleted++;
          break;
        case "line_remove":
          summary.linesRemoved++;
          break;
        case "block_remove":
          summary.blocksRemoved++;
          break;
        case "dependency_remove":
          summary.dependenciesRemoved++;
          break;
      }
    }

    this.report.summary = summary;
  }

  /**
   * Export report to JSON file
   */
  async exportReport(outputPath: string): Promise<string> {
    const reportPath = path.resolve(this.workingDir, outputPath);
    await fs.writeFile(reportPath, JSON.stringify(this.report, null, 2));
    return reportPath;
  }
}

interface ExecuteCleanupResult {
  report: CleanupReport;
  exitCode: number;
}

/**
 * Execute cleanup with given options
 */
export async function executeCleanup(options: CleanupEngineOptions = {}): Promise<ExecuteCleanupResult> {
  const engine = new CleanupEngine(options);

  try {
    await engine.loadConfig();
    const report = await engine.execute();

    if (options.report) {
      await engine.exportReport(options.report);
    }

    // Determine exit code based on failOnActions flag
    let exitCode = 0; // Success
    if (options.failOnActions && report.actions.length > 0) {
      exitCode = 2; // Actions detected
    }

    return { report, exitCode };
  } catch (error: any) {
    throw new Error(`Cleanup failed: ${error.message}`);
  }
}

const fs = require('fs').promises;
const path = require('path');

/**
 * Base class for all package managers
 * Provides shared logic for dependency pruning and lock file management
 */
class BasePackageManager {
  constructor(workingDir, dryRun) {
    this.workingDir = workingDir;
    this.dryRun = dryRun;
  }

  /**
   * Get the name of the package file (must be implemented by subclasses)
   * @returns {string} Package file name
   */
  getPackageFile() {
    throw new Error('getPackageFile must be implemented by subclass');
  }

  /**
   * Get the name of the lock file (must be implemented by subclasses)
   * @returns {string|null} Lock file name or null if no lock file
   */
  getLockFile() {
    throw new Error('getLockFile must be implemented by subclass');
  }

  /**
   * Read the package file (must be implemented by subclasses)
   * @param {string} filePath Path to package file
   * @returns {Promise<any>} Parsed package file content
   */
  async readPackageFile(filePath) {
    throw new Error('readPackageFile must be implemented by subclass');
  }

  /**
   * Write the package file (must be implemented by subclasses)
   * @param {string} filePath Path to package file
   * @param {any} content Content to write
   */
  async writePackageFile(filePath, content) {
    throw new Error('writePackageFile must be implemented by subclass');
  }

  /**
   * Remove dependencies from package file (must be implemented by subclasses)
   * @param {any} content Package file content
   * @param {object} rule Cleanup rule
   * @returns {Promise<{modified: boolean, removedDeps: string[]}>}
   */
  async removeDependencies(content, rule) {
    throw new Error('removeDependencies must be implemented by subclass');
  }

  /**
   * Get the manager name (defaults to class name without 'Manager' suffix)
   * @returns {string} Manager name
   */
  getManagerName() {
    return this.constructor.name.replace('Manager', '').toLowerCase();
  }

  /**
   * Main pruning logic - shared across all package managers
   * @param {object} rule Cleanup rule
   * @returns {Promise<{actions: Array}>} Actions taken
   */
  async prune(rule) {
    const actions = [];
    const packageFilePath = path.join(this.workingDir, this.getPackageFile());

    try {
      // Read package file
      const content = await this.readPackageFile(packageFilePath);

      // Remove dependencies
      const { modified, removedDeps } = await this.removeDependencies(content, rule);

      // Write back if modified
      if (modified && !this.dryRun) {
        await this.writePackageFile(packageFilePath, content);
        await this.removeLockFile();
      }

      // Record actions
      removedDeps.forEach(dep => {
        actions.push({
          type: 'dependency_remove',
          rule: rule.id,
          manager: this.getManagerName(),
          dependency: dep.name || dep,
          section: dep.section || undefined,
          dryRun: this.dryRun,
        });
      });
    } catch (error) {
      throw new Error(`Failed to prune ${this.getManagerName()}: ${error.message}`);
    }

    return { actions };
  }

  /**
   * Remove lock file if it exists
   */
  async removeLockFile() {
    const lockFile = this.getLockFile();
    if (!lockFile) return;

    const lockPath = path.join(this.workingDir, lockFile);
    try {
      await fs.access(lockPath);
      await fs.unlink(lockPath);
    } catch {
      // Lock file doesn't exist, ignore
    }
  }
}

