#!/usr/bin/env node
/**
 * Remove build output so a rebuild cannot inherit stale artifacts.
 *
 * `tsc --build --clean` only deletes files the current tsconfig would emit, so it leaves
 * behind output from previous directory layouts. Those orphans are load-bearing by accident:
 * tests that require a path the current build no longer produces still resolve against them
 * and pass locally while failing on a clean checkout. This removes the whole tree instead.
 */

const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..');

/** Build artifacts, relative to the repo root. */
const TARGETS = ['dist', 'tsconfig.tsbuildinfo'];

/**
 * Delete a build artifact if present.
 *
 * @param {string} relativeTarget Path relative to the repo root.
 * @returns {'removed' | 'skipped'} Whether anything was deleted.
 */
function removeTarget(relativeTarget) {
  const absoluteTarget = path.join(REPO_ROOT, relativeTarget);

  // Refuse to delete anything outside the repo, in case a caller passes a traversal path.
  if (!absoluteTarget.startsWith(REPO_ROOT + path.sep)) {
    throw new Error(`Refusing to delete outside the repository: ${relativeTarget}`);
  }

  if (!fs.existsSync(absoluteTarget)) {
    return 'skipped';
  }

  try {
    fs.rmSync(absoluteTarget, { recursive: true, force: true });
  } catch (error) {
    throw new Error(`Failed to remove ${relativeTarget}: ${error.message}`);
  }

  return 'removed';
}

function main() {
  let removedCount = 0;

  for (const target of TARGETS) {
    const outcome = removeTarget(target);

    if (outcome === 'removed') {
      removedCount += 1;
      console.log(`  removed  ${target}`);
    } else {
      console.log(`  skipped  ${target} (not present)`);
    }
  }

  console.log(
    removedCount > 0
      ? `Clean complete (${removedCount} of ${TARGETS.length} targets removed).`
      : 'Clean complete (nothing to remove).'
  );
}

try {
  main();
} catch (error) {
  console.error(`Clean failed: ${error.message}`);
  process.exit(1);
}

#!/usr/bin/env node

/**
 * Cursor Rules Integration
 * 
 * Handles copying and merging cursor rules from .devenv/.cursor/rules to project.
 */

import { promises as fs } from 'fs';
import path from 'path';
import type { StackReport, CursorRulesInfo } from '../types/gaps';
import { createLogger } from '../utils/logger';
import {
  detectExistingRules,
  shouldIncludeRule,
  HOST_CORE_FILES,
  STANDARD_CORE_FILES,
  STANDARD_CONDITIONAL_FILES
} from './cursor-rules-adapter';

const logger = createLogger({ context: 'cursor-rules-integration' });

export interface IntegrationOptions {
  projectRoot: string;
  templateRulesPath: string;
  stackReport: StackReport;
  overwriteCore?: boolean;
  dryRun?: boolean;
}

export interface IntegrationResult {
  copied: string[];
  updated: string[];
  preserved: string[];
  skipped: string[];
  conflicts: string[];
  recommendations: string[];
}

/**
 * Copy core rules from template to project
 */
async function copyCoreRules(
  templatePath: string,
  projectPath: string,
  overwrite: boolean
): Promise<string[]> {
  const copied: string[] = [];

  // Ensure project directory exists
  await fs.mkdir(projectPath, { recursive: true });

  for (const coreFile of HOST_CORE_FILES) {
    const templateFile = path.join(templatePath, coreFile);
    const projectFile = path.join(projectPath, coreFile);

    try {
      // Check if template file exists
      await fs.access(templateFile);

      // Check if project file exists
      const projectExists = await fs.access(projectFile).then(() => true).catch(() => false);

      if (!projectExists || overwrite) {
        // Copy file
        const content = await fs.readFile(templateFile, 'utf8');
        await fs.writeFile(projectFile, content, 'utf8');
        copied.push(coreFile);
      }
    } catch (error: any) {
      if (error.code !== 'ENOENT') {
        logger.warn(`Error copying core rule ${coreFile}`, { error: error.message });
      }
    }
  }

  return copied;
}

/**
 * Copy conditional rules based on stack
 */
async function copyConditionalRules(
  templatePath: string,
  projectPath: string,
  stackReport: StackReport
): Promise<string[]> {
  const copied: string[] = [];

  // Ensure project directory exists
  await fs.mkdir(projectPath, { recursive: true });

  for (const conditionalFile of STANDARD_CONDITIONAL_FILES) {
    if (!shouldIncludeRule(conditionalFile, stackReport)) {
      continue;
    }

    const templateFile = path.join(templatePath, conditionalFile);
    const projectFile = path.join(projectPath, conditionalFile);

    try {
      // Check if template file exists
      await fs.access(templateFile);

      // Check if project file exists
      const projectExists = await fs.access(projectFile).then(() => true).catch(() => false);

      if (!projectExists) {
        // Copy file (don't overwrite existing project files)
        const content = await fs.readFile(templateFile, 'utf8');
        await fs.writeFile(projectFile, content, 'utf8');
        copied.push(conditionalFile);
      }
    } catch (error: any) {
      if (error.code !== 'ENOENT') {
        logger.warn(`Error copying conditional rule ${conditionalFile}`, { error: error.message });
      }
    }
  }

  return copied;
}

/**
 * Preserve project-specific rules
 */
async function preserveProjectRules(projectPath: string): Promise<string[]> {
  const preserved: string[] = [];

  try {
    const entries = await fs.readdir(projectPath, { withFileTypes: true });

    for (const entry of entries) {
      if (entry.isFile() && entry.name.endsWith('.mdc')) {
        // Check if it's a project-specific file (not in standard list)
        const isStandard =
          STANDARD_CORE_FILES.includes(entry.name) ||
          STANDARD_CONDITIONAL_FILES.includes(entry.name);

        if (!isStandard) {
          preserved.push(entry.name);
        }
      }
    }
  } catch (error: any) {
    if (error.code !== 'ENOENT') {
      logger.warn('Error preserving project rules', { error: error.message });
    }
  }

  return preserved;
}

/**
 * Copy README if it exists
 */
async function copyReadme(
  templatePath: string,
  projectPath: string
): Promise<boolean> {
  const templateReadme = path.join(templatePath, 'README.md');
  const projectReadme = path.join(projectPath, 'README.md');

  try {
    await fs.access(templateReadme);
    const content = await fs.readFile(templateReadme, 'utf8');

    // Check if project README exists
    const projectExists = await fs.access(projectReadme).then(() => true).catch(() => false);

    if (!projectExists) {
      await fs.writeFile(projectReadme, content, 'utf8');
      return true;
    }
  } catch (error: any) {
    if (error.code !== 'ENOENT') {
      logger.warn('Error copying README', { error: error.message });
    }
  }

  return false;
}

/**
 * Main integration function
 */
export async function integrateCursorRules(
  options: IntegrationOptions
): Promise<IntegrationResult> {
  const {
    projectRoot,
    templateRulesPath,
    stackReport,
    overwriteCore = false,
    dryRun = false
  } = options;

  const result: IntegrationResult = {
    copied: [],
    updated: [],
    preserved: [],
    skipped: [],
    conflicts: [],
    recommendations: []
  };

  const projectRulesPath = path.join(projectRoot, '.cursor', 'rules');

  // Detect existing rules
  const existingRules = await detectExistingRules(projectRoot);

  if (dryRun) {
    logger.info('[DRY RUN] Would integrate cursor rules', {
      projectPath: projectRulesPath,
      templatePath: templateRulesPath,
      existingRules: existingRules.existingFiles.length
    });
    return result;
  }

  // Ensure project directory exists
  await fs.mkdir(projectRulesPath, { recursive: true });

  // Preserve project-specific rules
  if (existingRules.present) {
    result.preserved = await preserveProjectRules(projectRulesPath);
  }

  // Copy core rules
  const copiedCore = await copyCoreRules(templateRulesPath, projectRulesPath, overwriteCore);
  result.copied.push(...copiedCore);

  // For existing core files that weren't overwritten, mark as updated if they exist
  if (existingRules.present && !overwriteCore) {
    for (const coreFile of HOST_CORE_FILES) {
      if (existingRules.coreFiles.includes(coreFile) && !copiedCore.includes(coreFile)) {
        result.updated.push(coreFile);
      }
    }
  }

  // Copy conditional rules based on stack
  const copiedConditional = await copyConditionalRules(
    templateRulesPath,
    projectRulesPath,
    stackReport
  );
  result.copied.push(...copiedConditional);

  // Copy README
  const readmeCopied = await copyReadme(templateRulesPath, projectRulesPath);
  if (readmeCopied) {
    result.copied.push('README.md');
  }

  // Generate recommendations
  if (result.preserved.length > 0) {
    result.recommendations.push(
      `Preserved ${result.preserved.length} project-specific rule file(s). Review them to ensure compatibility.`
    );
  }

  if (existingRules.present && existingRules.coreFiles.filter(f => HOST_CORE_FILES.includes(f)).length < HOST_CORE_FILES.length) {
    const missing = HOST_CORE_FILES.filter(f => !existingRules.coreFiles.includes(f));
    result.recommendations.push(
      `Added ${missing.length} missing core rule file(s).`
    );
  }

  logger.info('Cursor rules integration complete', {
    copied: result.copied.length,
    updated: result.updated.length,
    preserved: result.preserved.length
  });

  return result;
}

#!/usr/bin/env node

/**
 * Documentation Organizer CLI
 * 
 * Command-line tool for organizing markdown files into appropriate directories.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { resolveProjectRoot } from '../utils/path-resolver';
import {
  organizeDocumentation,
  validateOrganization,
  detectMisplacedDocs,
  loadDocsConfig,
  determineTargetDirectory
} from '../utils/docs-organizer';

interface CliOptions {
  dryRun?: boolean;
  autoFix?: boolean;
  config?: string;
  verbose?: boolean;
  projectRoot?: string;
}

/**
 * Format file path for display
 */
function formatPath(filePath: string, projectRoot: string): string {
  return path.relative(projectRoot, filePath).replace(/\\/g, '/');
}

/**
 * Main CLI function
 */
async function main() {
  const args = process.argv.slice(2);

  const options: CliOptions = {
    dryRun: args.includes('--dry-run'),
    autoFix: args.includes('--auto-fix'),
    verbose: args.includes('--verbose'),
  };

  // Parse --config option
  const configIndex = args.findIndex(arg => arg.startsWith('--config'));
  if (configIndex !== -1) {
    const configArg = args[configIndex];
    if (configArg.includes('=')) {
      options.config = configArg.split('=')[1];
    } else if (args[configIndex + 1]) {
      options.config = args[configIndex + 1];
    }
  }

  // Parse --project-root option
  const rootIndex = args.findIndex(arg => arg.startsWith('--project-root'));
  if (rootIndex !== -1) {
    const rootArg = args[rootIndex];
    if (rootArg.includes('=')) {
      options.projectRoot = rootArg.split('=')[1];
    } else if (args[rootIndex + 1]) {
      options.projectRoot = args[rootIndex + 1];
    }
  }

  // Resolve project root
  const currentDir = process.cwd();
  const projectRoot = options.projectRoot || resolveProjectRoot(currentDir) || currentDir;

  if (projectRoot !== currentDir) {
    process.chdir(projectRoot);
  }

  try {
    // Validate organization is needed
    const validation = await validateOrganization(projectRoot);

    if (!validation.needsOrganization) {
      console.log('Γ£à All documentation files are properly organized.\n');
      process.exit(0);
    }

    // Show what needs to be organized
    console.log('≡ƒôÜ Documentation Organization\n');
    console.log(`Found ${validation.misplacedFiles.length} file(s) that need organization:\n`);

    // Load config to show target directories
    const config = await loadDocsConfig(projectRoot);

    for (const filename of validation.misplacedFiles) {
      const { target, reason } = determineTargetDirectory(filename, config, projectRoot);
      const targetRelative = formatPath(target, projectRoot);
      console.log(`  ΓÇó ${filename}`);
      console.log(`    ΓåÆ ${targetRelative}/`);
      if (options.verbose) {
        console.log(`    Reason: ${reason}`);
      }
    }

    // If dry-run or not auto-fix, show preview
    if (options.dryRun || !options.autoFix) {
      console.log('\n' + '='.repeat(50));
      console.log('DRY RUN MODE - No files will be moved');
      console.log('='.repeat(50) + '\n');

      const result = await organizeDocumentation(projectRoot, true);

      if (result.conflicts.length > 0) {
        console.log('\nΓÜá∩╕Å  Conflicts detected:');
        for (const conflict of result.conflicts) {
          console.log(`  ΓÇó ${formatPath(conflict.source, projectRoot)}`);
          console.log(`    Target already exists: ${formatPath(conflict.target, projectRoot)}`);
        }
      }

      if (result.errors.length > 0) {
        console.log('\nΓ¥î Errors:');
        for (const error of result.errors) {
          console.log(`  ΓÇó ${error}`);
        }
      }

      console.log('\nTo apply changes, run with --auto-fix flag:');
      console.log('  devenv organize-docs --auto-fix\n');

      process.exit(0);
    }

    // Auto-fix mode
    console.log('\n' + '='.repeat(50));
    console.log('AUTO-FIX MODE - Files will be moved');
    console.log('='.repeat(50) + '\n');

    const result = await organizeDocumentation(projectRoot, false);

    if (result.filesToMove.length > 0) {
      console.log(`Γ£à Moved ${result.filesToMove.length} file(s):\n`);
      for (const move of result.filesToMove) {
        console.log(`  ΓÇó ${formatPath(move.source, projectRoot)}`);
        console.log(`    ΓåÆ ${formatPath(move.target, projectRoot)}`);
        if (options.verbose) {
          console.log(`    Reason: ${move.reason}`);
        }
      }
    }

    if (result.conflicts.length > 0) {
      console.log('\nΓÜá∩╕Å  Conflicts (files not moved):');
      for (const conflict of result.conflicts) {
        console.log(`  ΓÇó ${formatPath(conflict.source, projectRoot)}`);
        console.log(`    ${conflict.message}`);
      }
    }

    if (result.errors.length > 0) {
      console.log('\nΓ¥î Errors:');
      for (const error of result.errors) {
        console.log(`  ΓÇó ${error}`);
      }
      process.exit(1);
    }

    if (result.success) {
      console.log('\nΓ£à Documentation organization complete!\n');
      process.exit(0);
    } else {
      console.log('\nΓ¥î Organization completed with errors\n');
      process.exit(1);
    }

  } catch (error: any) {
    console.error(`\nΓ¥î Error: ${error.message}\n`);
    if (options.verbose) {
      console.error(error.stack);
    }
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main().catch((error) => {
    console.error('Fatal error:', error);
    process.exit(1);
  });
}

export { main };

#!/usr/bin/env node

/**
 * Gap Analyzer - CI-only utility
 *
 * Analyzes detected stack against development best practices
 * and generates recommendations for improvement.
 * 
 * Enhanced with comprehensive checks for documentation, dependencies,
 * performance, accessibility, Docker, environment variables, and git hooks.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { createLogger } from '../../scripts/utils/logger';
import type { Gap, StackReport, GapReport, GapAnalysisOptions } from '../types/gaps';

const logger = createLogger({ context: 'gap-analyzer' });
const cliArgs = process.argv.slice(2);
const debugFlag = cliArgs.includes('--debug');
if (debugFlag && !process.env.LOG_LEVEL) {
  process.env.LOG_LEVEL = 'DEBUG';
}
let parsedMode: 'fast' | 'full' | undefined;
const inlineModeArg = cliArgs.find(arg => arg.startsWith('--mode='));
if (inlineModeArg) {
  const value = inlineModeArg.split('=')[1];
  if (value === 'fast' || value === 'full') {
    parsedMode = value;
  }
}
if (!parsedMode) {
  const modeIndex = cliArgs.indexOf('--mode');
  if (modeIndex !== -1 && (cliArgs[modeIndex + 1] === 'fast' || cliArgs[modeIndex + 1] === 'full')) {
    parsedMode = cliArgs[modeIndex + 1] as 'fast' | 'full';
  }
}
if (!parsedMode && (cliArgs.includes('--fast') || cliArgs.includes('--shallow'))) {
  parsedMode = 'fast';
}
if (!parsedMode && cliArgs.includes('--full')) {
  parsedMode = 'full';
}
const analyzerMode: 'fast' | 'full' = parsedMode === 'fast' ? 'fast' : 'full';
const NODE_TECH_HINTS = ['node.js', 'node', 'react', 'next.js', 'nextjs', 'vite', 'express', 'typescript', 'javascript', 'svelte'];
const PYTHON_TECH_HINTS = ['python', 'fastapi', 'django', 'flask', 'pytest', 'black', 'ruff', 'mypy', 'pytorch', 'pychrono', 'numpy', 'scipy', 'pandas'];
const NODE_PACKAGE_MANAGERS = ['npm', 'pnpm', 'yarn', 'bun'];
const PYTHON_PACKAGE_MANAGERS = ['pip', 'pipenv', 'poetry', 'uv'];
const ENV_SAMPLE_FILES = ['.env.example', '.env.sample', 'env.example', 'env.sample', 'env-example.txt', 'env-example.env'];

class GapAnalyzer {
  private rootDir: string;
  private stack: StackReport | null = null;
  private gaps: Gap[] = [];
  private profiles: Set<string> = new Set();
  private languageProfile: string = 'agnostic';
  private mode: 'fast' | 'full';
  private debug: boolean;

  constructor(options: GapAnalysisOptions = {}) {
    this.rootDir = options.rootDir || process.cwd();
    this.mode = options.mode || analyzerMode;
    this.debug = !!options.debug;
  }

  async analyze(): Promise<string> {
    logger.info('Starting gap analysis against development best practices');

    // Load stack report
    try {
      const stackReportPath = path.join(this.rootDir, '.devenv', 'stack-report.json');
      const content = await fs.readFile(stackReportPath, 'utf8');
      this.stack = JSON.parse(content) as StackReport;
      const inferredProfiles = Array.isArray(this.stack.profiles) && this.stack.profiles.length > 0
        ? this.stack.profiles
        : this.detectProfilesFromStack();
      this.profiles = new Set(inferredProfiles);
      this.applyManifestProfiles();
      const stackLanguageProfile = (this.stack as any).languageProfile;
      if (typeof stackLanguageProfile === 'string' && stackLanguageProfile.length > 0) {
        this.languageProfile = stackLanguageProfile;
        this.syncProfilesWithLanguageProfile();
      } else {
        this.languageProfile = this.computeLanguageProfile();
      }
      logger.info('Stack report loaded successfully');
      this.logDebug('Stack report loaded', {
        profiles: Array.from(this.profiles),
        languageProfile: this.languageProfile
      });
    } catch (error) {
      logger.error('Stack report not found. Run stack-detector first.');
      throw new Error('Stack report not found. Run stack-detector first.');
    }

    if (this.isFastMode()) {
      logger.info('Fast mode enabled: skipping documentation, accessibility, Docker, and git-hook checks.');
    }

    await this.runStage('TypeScript', () => this.analyzeTypeScript());
    await this.runStage('Linting', () => this.analyzeLinting());
    await this.runStage('Testing', () => this.analyzeTesting());
    await this.runStage('Security', () => this.analyzeSecurity());
    await this.runStage('CI/CD', () => this.analyzeCI());
    await this.runStage('Boundaries', () => this.analyzeBoundaries());
    await this.runStage('Quality Gates', () => this.analyzeQualityGates());

    if (this.isFastMode()) {
      await this.runStage('Dependencies', () => this.analyzeDependencies());
      this.gaps.push({
        category: 'documentation',
        severity: 'low',
        title: 'Fast doctor run (partial coverage)',
        description: 'Fast mode skips documentation, accessibility, Docker, environment, and git-hook checks.',
        impact: 'Some gaps only appear in full scans.',
        recommendation: 'Re-run `npm run doctor --full` before releases for complete coverage.',
        effort: 'low',
        files: []
      });
      this.logDebug('Inserted fast-mode diagnostics gap');
    } else {
      await this.runStage('Documentation', () => this.analyzeDocumentation());
      await this.runStage('Dependencies', () => this.analyzeDependencies());
      await this.runStage('Performance', () => this.analyzePerformance());
      await this.runStage('Accessibility', () => this.analyzeAccessibility());
      await this.runStage('Docker', () => this.analyzeDocker());
      await this.runStage('Environment', () => this.analyzeEnvironment());
      await this.runStage('Git Hooks', () => this.analyzeGitHooks());
      await this.runStage('Frameworks', () => this.analyzeFrameworks());
      await this.runStage('Python Tooling', () => this.analyzePythonTooling());
    }

    logger.info(`Gap analysis complete. Found ${this.gaps.length} gaps`);
    this.logDebug('Gap analysis finished', { gaps: this.gaps.length, mode: this.mode });
    return this.generateReport();
  }

  private isFastMode(): boolean {
    return this.mode === 'fast';
  }

  private analyzeTypeScript(): void {
    if (!this.hasProfile('node')) {
      return;
    }
    const hasTypeScript = this.stack!.technologies.some(t => t.name === 'TypeScript');
    const hasTSConfig = this.stack!.configurations.some(c => c.type === 'typescript');

    if (!hasTypeScript) {
      this.gaps.push({
        category: 'typescript',
        severity: 'high',
        title: 'TypeScript Not Configured',
        description: 'TypeScript provides compile-time type checking and better IDE support.',
        impact: 'Reduces code quality and developer experience',
        recommendation: 'Add TypeScript dependency and tsconfig.json with strict settings',
        effort: 'medium',
        files: ['package.json', 'tsconfig.json'],
        resources: ['https://www.typescriptlang.org/docs/handbook/tsconfig-json.html']
      });
    } else if (!hasTSConfig) {
      this.gaps.push({
        category: 'typescript',
        severity: 'high',
        title: 'Missing TypeScript Configuration',
        description: 'TypeScript is installed but not properly configured.',
        impact: 'Type checking may not work correctly',
        recommendation: 'Create tsconfig.json with strict: true and proper compiler options',
        effort: 'low',
        files: ['tsconfig.json'],
        codeSnippet: `{
  "compilerOptions": {
    "target": "es2020",
    "module": "commonjs",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true
  }
}`
      });
    } else {
      const tsConfig = this.stack!.configurations.find(c => c.type === 'typescript');
      if (!tsConfig?.strict) {
        this.gaps.push({
          category: 'typescript',
          severity: 'medium',
          title: 'TypeScript Strict Mode Disabled',
          description: 'Strict mode provides better type safety but may require more explicit typing.',
          impact: 'Potential runtime errors from type issues',
          recommendation: 'Enable "strict": true in tsconfig.json',
          effort: 'medium',
          files: ['tsconfig.json']
        });
      }
    }
  }

