        severity: 'low',
        title: 'Environment Template Uses Non-Standard Name',
        description: `Found ${envSample}; renaming to .env.example keeps tooling (and DevEnvTemplate) happy.`,
        impact: 'Tooling like dotenv/pre-commit may not auto-detect the template file',
        recommendation: `Rename ${envSample} to .env.example and update docs referencing it`,
        effort: 'low',
        files: [envSample]
      });
    }

    // Check for .env in .gitignore
    try {
      const gitignore = await fs.readFile(path.join(this.rootDir, '.gitignore'), 'utf8');
      if (!gitignore.includes('.env')) {
        this.gaps.push({
          category: 'environment',
          severity: 'high',
          title: '.env Not in .gitignore',
          description: 'Environment files should never be committed',
          impact: 'Secrets may be accidentally committed to version control',
          recommendation: 'Add .env to .gitignore immediately',
          effort: 'low',
          files: ['.gitignore']
        });
      }
    } catch {
      // .gitignore not found
    }
  }

  private async analyzeGitHooks(): Promise<void> {
    const hasPreCommit = await this.fileExists('.pre-commit-config.yaml');
    const hasHusky = await this.fileExists('.husky');

    if (this.hasProfile('python') && !hasPreCommit) {
      this.gaps.push({
        category: 'git-hooks',
        severity: 'low',
        title: 'Pre-commit Hooks Not Configured',
        description: 'pre-commit keeps Ruff/Black/Mypy/Pytest in sync with CI for Python repos.',
        impact: 'Developers may skip the fast fail checks that CI enforces',
        recommendation: 'Add pre-commit with Ruff/Black/Mypy/Pytest stages and run `pre-commit install`',
        effort: 'low',
        files: ['.pre-commit-config.yaml'],
        codeSnippet: `repos:
  - repo: https://github.com/astral-sh/ruff-pre-commit
    rev: v0.6.9
    hooks:
      - id: ruff
  - repo: local
    hooks:
      - id: pytest
        entry: python -m pytest`,
        resources: ['https://pre-commit.com/']
      });
      return;
    }

    if (this.hasProfile('node') && !hasHusky) {
      this.gaps.push({
        category: 'git-hooks',
        severity: 'low',
        title: 'Git Hooks Not Configured',
        description: 'Pre-commit hooks prevent bad code from being committed',
        impact: 'Linting and formatting issues may be committed',
        recommendation: 'Add Husky with pre-commit hooks for lint and format',
        effort: 'low',
        files: ['package.json', '.husky/pre-commit'],
        codeSnippet: `npm install --save-dev husky
npx husky init
echo "npm run lint && npm run format:check" > .husky/pre-commit`
      });
    } else if (!hasPreCommit && !hasHusky) {
      this.gaps.push({
        category: 'git-hooks',
        severity: 'low',
        title: 'Git Hooks Not Configured',
        description: 'Pre-commit hooks (pre-commit or Husky) keep local workflows aligned with CI.',
        impact: 'Local commits may skip formatting/linting',
        recommendation: 'Add either pre-commit (Python) or Husky (Node) with lint/test tasks',
        effort: 'low',
        files: ['.pre-commit-config.yaml', '.husky/pre-commit']
      });
    }
  }

  private analyzeFrameworks(): void {
    const frameworks = {
      'React': ['prop-types', 'eslint-plugin-react-hooks'],
      'Next.js': ['next-seo', 'sharp'],
      'Vue': ['vue-router', 'pinia'],
      'Angular': ['@angular/cli', '@angular/forms']
    };

    Object.entries(frameworks).forEach(([framework, essentialPackages]) => {
      const hasFramework = this.stack!.technologies.some(t => t.name === framework);
      if (hasFramework) {
        this.gaps.push({
          category: 'quality',
          severity: 'low',
          title: `${framework} Best Practices Check`,
          description: `Ensure ${framework} best practices are followed`,
          impact: 'May miss framework-specific optimizations',
          recommendation: `Review ${framework} documentation and consider: ${essentialPackages.join(', ')}`,
          effort: 'low',
          files: ['package.json'],
          resources: [`https://react.dev/`, `https://nextjs.org/docs`]
        });
      }
    });
  }

  private analyzePythonTooling(): void {
    if (!this.hasProfile('python')) {
      return;
    }

    if (!this.hasTechnology('Black')) {
      this.gaps.push({
        category: 'quality',
        severity: 'medium',
        title: 'Black Formatter Not Enabled',
        description: 'Black provides opinionated formatting for Python projects and keeps diffs small.',
        impact: 'Inconsistent formatting slows down code reviews',
        recommendation: 'Add Black to pyproject.toml and run `black .` in CI or as a pre-commit hook',
        effort: 'low',
        files: ['pyproject.toml', 'pyproject.lock']
      });
    }

    if (!this.hasTechnology('Mypy')) {
      this.gaps.push({
        category: 'quality',
        severity: 'medium',
        title: 'Static Typing (Mypy) Missing',
        description: 'Mypy catches entire classes of runtime errors for Python services.',
        impact: 'Refactors may introduce silent type errors',
        recommendation: 'Add Mypy with `python -m mypy src/` and enable strict optional checking',
        effort: 'medium',
        files: ['mypy.ini', 'pyproject.toml']
      });
    }
  }

  private async findEnvSampleFile(): Promise<string | null> {
    for (const candidate of ENV_SAMPLE_FILES) {
      if (await this.fileExists(candidate)) {
        return candidate;
      }
    }
    return null;
  }

  private async fileExists(relativePath: string): Promise<boolean> {
    try {
      await fs.access(path.join(this.rootDir, relativePath));
      return true;
    } catch {
      return false;
    }
  }

  private detectProfilesFromStack(): string[] {
    const names = this.stack?.technologies?.map(t => t.name.toLowerCase()) || [];
    const profiles: string[] = [];

    if (names.some(name => NODE_TECH_HINTS.includes(name))) {
      profiles.push('node');
    }
    if (names.some(name => PYTHON_TECH_HINTS.includes(name))) {
      profiles.push('python');
    }

    if (profiles.length === 0) {
      profiles.push('agnostic');
    }

    return profiles;
  }

  private applyManifestProfiles(): void {
    const manifest = (this.stack as any)?.manifest;
    if (!manifest) {
      return;
    }

    const manifestTechs = Array.isArray(manifest.technologies)
      ? manifest.technologies.map((tech: string) => tech.toLowerCase())
      : [];
    const packageManager = (manifest.packageManager || '').toLowerCase();

    if (
      manifestTechs.some((tech: string) => NODE_TECH_HINTS.includes(tech)) ||
      NODE_PACKAGE_MANAGERS.includes(packageManager)
    ) {
      this.profiles.add('node');
    }

    if (
      manifestTechs.some((tech: string) => PYTHON_TECH_HINTS.includes(tech)) ||
      PYTHON_PACKAGE_MANAGERS.includes(packageManager)
    ) {
      this.profiles.add('python');
    }
  }

  private computeLanguageProfile(): string {
    if (this.profiles.has('node') && this.profiles.has('python')) {
      return 'python+node';
    }
    if (this.profiles.has('node')) {
      return 'node';
    }
    if (this.profiles.has('python')) {
      return 'python';
    }
    return 'agnostic';
  }

  private syncProfilesWithLanguageProfile(): void {
    if (this.languageProfile.includes('node')) {
      this.profiles.add('node');
    }
    if (this.languageProfile.includes('python')) {
      this.profiles.add('python');
    }
  }

  private hasProfile(profile: string): boolean {
    if (this.languageProfile === 'python+node') {
      return profile === 'python' || profile === 'node';
    }
    if (this.languageProfile === profile) {
      return true;
    }
    return this.profiles.has(profile);
  }

  private hasTechnology(name: string): boolean {
    const needle = name.toLowerCase();
    return this.stack!.technologies.some(t => t.name.toLowerCase() === needle);
  }

  private hasTestingFramework(name: string): boolean {
    const needle = name.toLowerCase();
    return (this.stack!.tooling?.testing?.frameworks || []).some(
      framework => framework.name.toLowerCase() === needle
    );
  }

  private generateReport(): string {
    // Sort gaps by severity
    const severityOrder = { high: 3, medium: 2, low: 1 };
    this.gaps.sort((a, b) => severityOrder[b.severity] - severityOrder[a.severity]);

    let report = '# Development Environment Gap Analysis Report\n\n';
    report += `Generated: ${new Date().toISOString()}\n\n`;
    report += `Total gaps found: ${this.gaps.length}\n\n`;

    // Group by category
    const categories: Record<string, Gap[]> = {};
    this.gaps.forEach(gap => {
      if (!categories[gap.category]) {
        categories[gap.category] = [];
      }
      categories[gap.category].push(gap);
    });

    // Generate sections
    Object.entries(categories).forEach(([category, gaps]) => {
      report += `## ${category.charAt(0).toUpperCase() + category.slice(1)} (${gaps.length} gaps)\n\n`;

      gaps.forEach(gap => {
        const severityIcon = gap.severity === 'high' ? '≡ƒö┤' : gap.severity === 'medium' ? '≡ƒƒí' : '≡ƒƒó';
        report += `### ${severityIcon} ${gap.title}\n\n`;
        report += `**Category:** ${gap.category}\n\n`;
        report += `${gap.description}\n\n`;
        report += `**Impact:** ${gap.impact}\n\n`;
        report += `**Recommendation:** ${gap.recommendation}\n\n`;
        report += `**Effort:** ${gap.effort}\n\n`;
        report += `**Files:** ${gap.files.join(', ')}\n\n`;

        if (gap.codeSnippet) {
          report += `**Code Example:**\n\`\`\`\n${gap.codeSnippet}\n\`\`\`\n\n`;
        }

        if (gap.resources && gap.resources.length > 0) {
          report += `**Resources:** ${gap.resources.map(r => `[Link](${r})`).join(', ')}\n\n`;
        }

        report += '---\n\n';
      });
    });

    // Summary
    const highPriority = this.gaps.filter(g => g.severity === 'high').length;
    const mediumPriority = this.gaps.filter(g => g.severity === 'medium').length;
    const lowPriority = this.gaps.filter(g => g.severity === 'low').length;

    report += '## Summary\n\n';
    report += `≡ƒö┤ High Priority: ${highPriority} gaps\n`;
    report += `≡ƒƒí Medium Priority: ${mediumPriority} gaps\n`;
    report += `≡ƒƒó Low Priority: ${lowPriority} gaps\n\n`;

    if (highPriority > 0) {
      report += '**Recommendation:** Address high-priority gaps first for maximum impact on code quality and security.\n\n';
    }

    report += '## Next Steps\n\n';
    report += '1. Review gaps and prioritize based on your project needs\n';
    report += '2. Use Cursor Plan mode to implement improvements\n';
    report += '3. Follow the [Prompt Lifecycle Guide](docs/guides/prompt-lifecycle.md)\n';
    report += '4. Re-run analysis after implementing changes\n\n';

    report += '---\n\n*Generated by Development Environment gap analyzer*';

    return report;
  }

  /**
   * Build the machine-readable gap report.
   *
   * This is the contract downstream consumers (the doctor, CI) should use. The markdown from
   * `generateReport()` is for humans only: re-parsing it costs the severity of every gap,
   * because markdown groups by category and encodes severity as an emoji in a heading.
   */
  buildGapReport(): GapReport {
    const categories = {} as Record<Gap['category'], Gap[]>;
    for (const gap of this.gaps) {
      if (!categories[gap.category]) {
        categories[gap.category] = [];
      }
      categories[gap.category].push(gap);
    }

    return {
      timestamp: new Date().toISOString(),
      totalGaps: this.gaps.length,
      highPriority: this.gaps.filter(gap => gap.severity === 'high').length,
      mediumPriority: this.gaps.filter(gap => gap.severity === 'medium').length,
      lowPriority: this.gaps.filter(gap => gap.severity === 'low').length,
      gaps: [...this.gaps],
      categories
    };
  }

  // Method to save report to file
  async saveReport(report: string): Promise<void> {
    const outputPath = path.join(this.rootDir, '.devenv', 'gaps-report.md');
    await fs.mkdir(path.dirname(outputPath), { recursive: true });
    await fs.writeFile(outputPath, report);
    logger.info(`Gap report saved to ${outputPath}`);
  }

  /** Write the structured report that the doctor consumes. */
  async saveJsonReport(): Promise<string> {
    const outputPath = path.join(this.rootDir, '.devenv', 'gaps-report.json');
    await fs.mkdir(path.dirname(outputPath), { recursive: true });
    await fs.writeFile(outputPath, `${JSON.stringify(this.buildGapReport(), null, 2)}\n`);
    logger.info(`Structured gap report saved to ${outputPath}`);
    return outputPath;
  }
}

// Run the analyzer
if (require.main === module) {
  const analyzer = new GapAnalyzer({ mode: analyzerMode, debug: debugFlag });
  analyzer.analyze()
    .then(async report => {
      console.log(report);
      await analyzer.saveReport(report);
      await analyzer.saveJsonReport();
    })
    .catch(error => {
      logger.error('Gap analysis failed', { error: error.message });
      process.exit(1);
    });
}

export default GapAnalyzer;

#!/usr/bin/env node

/**
 * Encryption Key Generation Tool
 * 
 * CLI tool for generating encryption keys with proper base64 encoding.
 * Supports different key lengths and formats.
 * 
 * Usage:
 *   node dist/scripts/tools/generate-key.js [--length 32] [--format base64|hex]
 */

import { Command } from 'commander';
import { generateEncryptionKey, validateBase64Key, getExpectedBase64Length } from '../utils/crypto-helpers';

const program = new Command();

program
  .name('generate-key')
  .description('Generate encryption keys with proper base64 encoding')
  .version('1.0.0')
  .option('-l, --length <bytes>', 'Key length in bytes (default: 32)', '32')
  .option('-f, --format <format>', 'Output format: base64 or hex (default: base64)', 'base64')
  .option('-v, --validate', 'Validate the generated key', false)
  .option('--quiet', 'Only output the key (no additional messages)', false)
  .parse(process.argv);

const options = program.opts();

async function main() {
  const length = parseInt(options.length, 10);

  if (isNaN(length) || length <= 0) {
    console.error('Error: Length must be a positive number');
    process.exit(1);
  }

  if (length < 16) {
    console.error('Error: Key length must be at least 16 bytes for security');
    process.exit(1);
  }

  let key: string;

  if (options.format === 'hex') {
    // Generate hex format
    const crypto = require('crypto');
    key = crypto.randomBytes(length).toString('hex');
  } else {
    // Generate base64 format (default)
    key = generateEncryptionKey(length);
  }

  // Validate if requested
  if (options.validate && options.format === 'base64') {
    const validation = validateBase64Key(key, length);
    if (!validation.valid) {
      console.error(`Error: Generated key failed validation: ${validation.error}`);
      process.exit(1);
    }
  }

  // Output
  if (options.quiet) {
    console.log(key);
  } else {
    console.log('Generated encryption key:');
    console.log('');
    console.log(key);
    console.log('');
    if (options.format === 'base64') {
      const expectedLength = getExpectedBase64Length(length);
      console.log(`Key details:`);
      console.log(`  Format: Base64 URL-safe`);
      console.log(`  Length: ${length} bytes (${expectedLength} base64 characters)`);
      console.log(`  Valid: ${validateBase64Key(key, length).valid ? 'Yes' : 'No'}`);
    } else {
      console.log(`Key details:`);
      console.log(`  Format: Hexadecimal`);
      console.log(`  Length: ${length} bytes (${length * 2} hex characters)`);
    }
    console.log('');
    console.log('Usage:');
    console.log(`  export ENCRYPTION_KEY="${key}"`);
    console.log(`  # Or add to .env file:`);
    console.log(`  ENCRYPTION_KEY="${key}"`);
  }
}

main().catch((error) => {
  console.error('Error:', error.message);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * Plan Generator - CI-only utility
 *
 * Generates a hardening plan from gap analysis results.
 * Creates actionable tasks with code snippets, dependency ordering, and priority scoring.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { createLogger, Logger } from '../../scripts/utils/logger';
import { Gap, GapCategory } from '../types/gaps';
import { Task, TaskGroup, HardeningPlan, CodeSnippet, PlanGeneratorOptions, PlanMetadata } from '../types/plan';

export class PlanGenerator {
  private rootDir: string;
  private gaps: Gap[];
  private tasks: Task[];
  private logger: Logger;
  private includeCodeSnippets: boolean;
  private includeDependencies: boolean;
  private sortByPriority: boolean;

  constructor(options: PlanGeneratorOptions = {}) {
    this.rootDir = options.rootDir || process.cwd();
    this.gaps = [];
    this.tasks = [];
    this.logger = createLogger({ context: 'PlanGenerator' });
    this.includeCodeSnippets = options.includeCodeSnippets !== false;
    this.includeDependencies = options.includeDependencies !== false;
    this.sortByPriority = options.sortByPriority !== false;
  }

  public async generate(): Promise<string> {
    this.logger.info('≡ƒôï Generating hardening plan from gap analysis...');

    // Load gaps report
    try {
      const gapsReportPath = path.join(this.rootDir, '.devenv', 'gaps-report.md');
      const gapsReport = await fs.readFile(gapsReportPath, 'utf8');
      this.parseGaps(gapsReport);
      this.logger.debug(`Parsed ${this.gaps.length} gaps from report`);
    } catch (error: any) {
      this.logger.error('Failed to load gaps report. Run gap-analyzer first.', { error: error.message });
      throw new Error('Gaps report not found. Run gap-analyzer first.');
    }

    // Convert gaps to tasks
    this.tasks = this.gaps.map((gap, index) => this.gapToTask(gap, index + 1));

    // Calculate priority scores
    this.calculatePriorityScores();

    // Add dependencies if enabled
    if (this.includeDependencies) {
      this.calculateDependencies();
    }

    // Add code snippets if enabled
    if (this.includeCodeSnippets) {
      this.addCodeSnippets();
    }

    // Sort by priority score if enabled
    if (this.sortByPriority) {
      this.tasks.sort((a, b) => b.priorityScore - a.priorityScore);
      // Renumber tasks after sorting
      this.tasks.forEach((task, index) => {
        task.number = index + 1;
      });
    }

    this.logger.info(`Generated plan with ${this.tasks.length} tasks`);
    return this.generatePlanMarkdown();
  }

  private parseGaps(report: string): void {
    const lines = report.split('\n');
    let currentGap: Partial<Gap> | null = null;
    let inSection: 'description' | 'impact' | 'recommendation' | 'files' | 'resources' | null = null;

    for (const line of lines) {
      if (line.startsWith('### ')) {
        if (currentGap && currentGap.title) {
          this.gaps.push(currentGap as Gap);
        }

        // Match pattern: "### ≡ƒö┤ Title" or "### ≡ƒƒí Title" or "### ≡ƒƒó Title"
        // Emojis are multi-byte, so use a flexible pattern
        const titleMatch = line.match(/^### .+ (.+)$/);
        if (titleMatch) {
          const severity = line.includes('≡ƒö┤') ? 'high' : line.includes('≡ƒƒí') ? 'medium' : 'low';
          // Extract title by removing "### " and the emoji
          const title = line.replace(/^### [≡ƒö┤≡ƒƒí≡ƒƒó] /, '');
          currentGap = {
            title: title,
            severity: severity as 'high' | 'medium' | 'low',
            category: 'typescript' as GapCategory, // Will be overwritten when parsed
            description: '',
            impact: '',
            recommendation: '',
            effort: 'medium' as 'low' | 'medium' | 'high',
            files: [],
            resources: []
          };
          inSection = null;
        }
      } else if (currentGap) {
        if (line.startsWith('**Category:**')) {
          const categoryStr = line.replace('**Category:**', '').trim();
          currentGap.category = categoryStr as GapCategory;
        } else if (line.trim() && !line.startsWith('**') && !line.startsWith('---') && !currentGap.description) {
          currentGap.description = line.trim();
        } else if (line.startsWith('**Impact:**')) {
          currentGap.impact = line.replace('**Impact:**', '').trim();
          inSection = 'impact';
        } else if (line.startsWith('**Recommendation:**')) {
          currentGap.recommendation = line.replace('**Recommendation:**', '').trim();
          inSection = 'recommendation';
        } else if (line.startsWith('**Effort:**')) {
          const effortStr = line.replace('**Effort:**', '').trim().toLowerCase();
          currentGap.effort = (effortStr === 'low' || effortStr === 'medium' || effortStr === 'high') ? effortStr : 'medium';
          inSection = null;
        } else if (line.startsWith('**Files:**')) {
          const filesStr = line.replace('**Files:**', '').trim();
          currentGap.files = filesStr ? filesStr.split(',').map(f => f.trim()) : [];
          inSection = 'files';
        } else if (line.startsWith('**Resources:**')) {
          inSection = 'resources';
        } else if (line.startsWith('- ') && inSection === 'resources') {
          const url = line.replace(/^- /, '').trim();
          currentGap.resources = currentGap.resources || [];
          currentGap.resources.push(url);
        } else if (inSection && line.trim() && !line.startsWith('**') && !line.startsWith('---')) {
          // Continuation of previous section
          if (inSection === 'impact' && currentGap.impact) {
            currentGap.impact += ' ' + line.trim();
          } else if (inSection === 'recommendation' && currentGap.recommendation) {
            currentGap.recommendation += ' ' + line.trim();
          }
        }
      }
    }

    if (currentGap && currentGap.title) {
      this.gaps.push(currentGap as Gap);
    }
  }

  private gapToTask(gap: Gap, number: number): Task {
    return {
      id: this.generateTaskId(gap),
      number,
      title: gap.title,
      description: gap.description,
      priority: gap.severity,
      severity: gap.severity,
      effort: gap.effort,
      impact: gap.impact,
      recommendation: gap.recommendation,
      category: gap.category,
      files: gap.files || [],
      resources: gap.resources || [],
      codeSnippets: [],
      dependencies: [],
      estimatedMinutes: this.estimateEffort(gap.effort),
      priorityScore: 0
    };
  }

  private generateTaskId(gap: Gap): string {
    return gap.title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }

  private estimateEffort(effort: 'low' | 'medium' | 'high'): number {
    const estimates = {
      low: 30,
      medium: 90,
      high: 180
    };
    return estimates[effort];
  }

  private calculatePriorityScores(): void {
    const severityWeight = { high: 10, medium: 5, low: 2 };
    const effortWeight = { low: 3, medium: 2, high: 1 }; // Low effort = higher score (easier win)

    this.tasks.forEach(task => {
      const severityScore = severityWeight[task.severity];
      const effortScore = effortWeight[task.effort];
      task.priorityScore = severityScore * effortScore;
    });
  }

  private calculateDependencies(): void {
    // Define common dependency patterns
    const dependencyRules = [
      {
        // TypeScript should be set up before ESLint TypeScript config
        if: (task: Task) => task.category === 'linting' && task.title.toLowerCase().includes('typescript'),
        dependsOn: (tasks: Task[]) => tasks.find(t => t.category === 'typescript' && t.title.toLowerCase().includes('not configured')),
        reason: 'TypeScript must be configured before TypeScript ESLint rules'
      },
      {
        // Testing framework before E2E tests
        if: (task: Task) => task.category === 'testing' && task.title.toLowerCase().includes('e2e'),
        dependsOn: (tasks: Task[]) => tasks.find(t => t.category === 'testing' && t.title.toLowerCase().includes('framework')),
        reason: 'Base testing framework required for E2E tests'
      },
      {
        // CI setup before CI quality gates
        if: (task: Task) => task.category === 'ci' && task.title.toLowerCase().includes('quality gate'),
        dependsOn: (tasks: Task[]) => tasks.find(t => t.category === 'ci' && t.title.toLowerCase().includes('not configured')),
        reason: 'CI pipeline must exist before adding quality gates'
      }
    ];

    this.tasks.forEach(task => {
      dependencyRules.forEach(rule => {
        if (rule.if(task)) {
          const dependency = rule.dependsOn(this.tasks);
          if (dependency && dependency.id !== task.id) {
            task.dependencies = task.dependencies || [];
            task.dependencies.push({
              taskId: dependency.id,
              reason: rule.reason
            });
          }
        }
      });
    });
  }

  private addCodeSnippets(): void {
    this.tasks.forEach(task => {
      task.codeSnippets = this.generateCodeSnippetsForTask(task);
    });
  }

  private generateCodeSnippetsForTask(task: Task): CodeSnippet[] {
    const snippets: CodeSnippet[] = [];

    // TypeScript configuration
    if (task.category === 'typescript' && task.title.toLowerCase().includes('not configured')) {
      snippets.push({
        language: 'json',
        filename: 'tsconfig.json',
        description: 'Basic TypeScript configuration with strict mode',
        code: `{
  "compilerOptions": {
    "target": "es2020",
    "module": "commonjs",
    "lib": ["es2020"],
    "outDir": "./dist",
    "rootDir": "./src",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true,
    "resolveJsonModule": true,
    "declaration": true,
    "sourceMap": true
  },
  "include": ["src/**/*"],
  "exclude": ["node_modules", "dist"]
}`
      });
      snippets.push({
        language: 'bash',
        description: 'Install TypeScript',
        code: `npm install --save-dev typescript @types/node`
      });
    }

    // ESLint configuration
    if (task.category === 'linting' && task.title.toLowerCase().includes('eslint')) {
      snippets.push({
        language: 'json',
        filename: '.eslintrc.json',
        description: 'ESLint configuration',
        code: `{
  "env": {
    "node": true,
    "es2021": true
  },
  "extends": ["eslint:recommended"],
  "parserOptions": {
    "ecmaVersion": 12,
    "sourceType": "module"
  },
  "rules": {
    "no-console": "warn",
    "no-unused-vars": "error"
  }
}`
      });
      snippets.push({
        language: 'bash',
        description: 'Install ESLint',
        code: `npm install --save-dev eslint`
      });
    }

    // Testing framework
    if (task.category === 'testing' && task.title.toLowerCase().includes('framework')) {
      snippets.push({
        language: 'bash',
        description: 'Node.js native test runner (recommended)',
        code: `# Node.js 18+ has built-in test runner
node --test tests/**/*.test.js`
      });
      snippets.push({
        language: 'json',
        filename: 'package.json',
        description: 'Add test script',
        code: `{
  "scripts": {
    "test": "node --test tests/**/*.test.js",
    "test:watch": "node --test --watch tests/**/*.test.js"
  }
}`
      });
    }

    // GitHub Actions CI
    if (task.category === 'ci' && task.title.toLowerCase().includes('not configured')) {
      snippets.push({
        language: 'yaml',
        filename: '.github/workflows/ci.yml',
        description: 'Basic CI workflow',
        code: `name: CI

on:
  push:
    branches: [main, master]
  pull_request:
    branches: [main, master]

jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - run: npm ci
      - run: npm test
      - run: npm run lint`
      });
    }

    // .env.example
    if (task.category === 'environment' && task.title.toLowerCase().includes('.env.example')) {
      snippets.push({
        language: 'bash',
        filename: '.env.example',
        description: 'Environment variable template',
        code: `# Application
NODE_ENV=development
PORT=3000

# Database
DATABASE_URL=postgresql://user:pass@localhost:5432/db

# API Keys (replace with your own)
API_KEY=your_api_key_here`
      });
    }

    // .dockerignore
    if (task.category === 'docker' && task.title.toLowerCase().includes('dockerignore')) {
      snippets.push({
        language: 'text',
        filename: '.dockerignore',
        description: 'Docker ignore file',
        code: `node_modules
npm-debug.log
dist
.git
.env
.DS_Store
*.md
tests
coverage`
      });
    }

    // Git hooks with Husky
    if (task.category === 'git' && task.title.toLowerCase().includes('hook')) {
      snippets.push({
        language: 'bash',
        description: 'Install Husky',
        code: `npm install --save-dev husky
npx husky install
npx husky add .husky/pre-commit "npm test"
npx husky add .husky/pre-commit "npm run lint"`
      });
    }

    return snippets;
  }

  private generatePlanMarkdown(): string {
    const metadata = this.generateMetadata();
    const taskGroups = this.groupTasksByPriority();

    let plan = '# Development Environment Hardening Plan\n\n';
    plan += `**Generated:** ${metadata.generatedAt}\n`;
    plan += `**Version:** ${metadata.version}\n\n`;
    plan += '> This plan outlines specific, actionable tasks to align your project with development best practices.\n';
    plan += '> Tasks are prioritized by impact and include code snippets for quick implementation.\n\n';

    // Plan Summary
    plan += '## ≡ƒôè Plan Summary\n\n';
    plan += `- **Total Tasks:** ${metadata.totalTasks}\n`;
    plan += `- **Estimated Time:** ${metadata.totalEstimatedHours.toFixed(1)} hours\n`;
    plan += `- **Critical Tasks:** ${metadata.criticalTasks} ≡ƒö┤\n`;
    plan += `- **Quick Wins:** ${metadata.quickWins} ≡ƒÆí (low effort, high impact)\n\n`;
    plan += `**Breakdown:**\n`;
    plan += `- ≡ƒÜ¿ High Priority: ${taskGroups.find(g => g.priority === 'high')?.tasks.length || 0} tasks\n`;
    plan += `- ΓÜá∩╕Å Medium Priority: ${taskGroups.find(g => g.priority === 'medium')?.tasks.length || 0} tasks\n`;
    plan += `- ≡ƒÆí Low Priority: ${taskGroups.find(g => g.priority === 'low')?.tasks.length || 0} tasks\n\n`;

    // Quick Wins
    const quickWins = this.identifyQuickWins();
    if (quickWins.length > 0) {
      plan += '## ≡ƒÜÇ Quick Wins\n\n';
      plan += '*Start here for fast, high-impact improvements (Γëñ30 min, high severity)*\n\n';
      quickWins.forEach(task => {
        plan += `- **Task ${task.number}**: ${task.title} (~${task.estimatedMinutes} min)\n`;
      });
      plan += '\n';
    }

    // Task Groups
    taskGroups.forEach(group => {
      plan += this.generateTaskGroupMarkdown(group);
    });

    // Implementation Guidelines
    plan += this.generateImplementationGuidelines();

    // Success Metrics
    plan += this.generateSuccessMetrics();

    // Resources
    plan += this.generateResources();

    plan += '---\n\n';
    plan += '*Auto-generated by Development Environment Plan Generator*\n';
    plan += '*Follow the [Prompt Lifecycle Guide](../docs/guides/prompt-lifecycle.md) for best results*\n';

    return plan;
  }

  private generateMetadata(): PlanMetadata {
    const totalMinutes = this.tasks.reduce((sum, task) => sum + task.estimatedMinutes, 0);
    const quickWins = this.identifyQuickWins();

    return {
      generatedAt: new Date().toISOString(),
      totalTasks: this.tasks.length,
      totalEstimatedHours: totalMinutes / 60,
      quickWins: quickWins.length,
      criticalTasks: this.tasks.filter(t => t.severity === 'high').length,
      version: '1.0.0'
    };
  }

  private groupTasksByPriority(): TaskGroup[] {
    const groups: TaskGroup[] = [
      {
        priority: 'high',
        title: '≡ƒÜ¿ High Priority Tasks',
        description: 'Address these first for maximum impact on quality and security.',
        tasks: this.tasks.filter(t => t.priority === 'high'),
        totalEffort: 0,
        totalImpact: 0
      },
      {
        priority: 'medium',
        title: 'ΓÜá∩╕Å Medium Priority Tasks',
        description: 'Important improvements that enhance maintainability and developer experience.',
        tasks: this.tasks.filter(t => t.priority === 'medium'),
        totalEffort: 0,
        totalImpact: 0
      },
      {
        priority: 'low',
        title: '≡ƒÆí Low Priority Tasks',
        description: 'Quality of life improvements that can be addressed when time allows.',
        tasks: this.tasks.filter(t => t.priority === 'low'),
        totalEffort: 0,
        totalImpact: 0
      }
    ];

    groups.forEach(group => {
      group.totalEffort = group.tasks.reduce((sum, task) => sum + task.estimatedMinutes, 0);
    });

    return groups;
  }

  private identifyQuickWins(): Task[] {
    return this.tasks.filter(task =>
      task.effort === 'low' && (task.severity === 'high' || task.severity === 'medium')
    );
  }

  private generateTaskGroupMarkdown(group: TaskGroup): string {
    if (group.tasks.length === 0) {
      return '';
    }

    let md = `## ${group.title}\n\n`;
    md += `${group.description}\n\n`;
    md += `*Total estimated time: ${(group.totalEffort / 60).toFixed(1)} hours*\n\n`;

    group.tasks.forEach(task => {
      md += this.generateTaskMarkdown(task);
    });

    return md;
  }

  private generateTaskMarkdown(task: Task): string {
    let md = `### Task ${task.number}: ${task.title}\n\n`;
    md += `${task.description}\n\n`;
    md += `| Property | Value |\n`;
    md += `|----------|-------|\n`;
    md += `| **Priority** | ${this.formatPriority(task.priority)} |\n`;
    md += `| **Effort** | ${task.effort} (~${task.estimatedMinutes} min) |\n`;
    md += `| **Category** | ${task.category} |\n`;
    md += `| **Priority Score** | ${task.priorityScore} |\n\n`;

    // Impact
    md += `**≡ƒÆÑ Impact:**\n${task.impact}\n\n`;

    // Recommendation
    md += `**Γ£à Recommendation:**\n${task.recommendation}\n\n`;

    // Dependencies
    if (task.dependencies && task.dependencies.length > 0) {
      md += `**ΓÜá∩╕Å Dependencies:**\n`;
      task.dependencies.forEach(dep => {
        const depTask = this.tasks.find(t => t.id === dep.taskId);
        if (depTask) {
          md += `- **Task ${depTask.number}** (${depTask.title}): ${dep.reason}\n`;
        }
      });
      md += '\n';
    }

    // Code Snippets
    if (task.codeSnippets && task.codeSnippets.length > 0) {
      md += `**≡ƒô¥ Implementation:**\n\n`;
      task.codeSnippets.forEach(snippet => {
        if (snippet.description) {
          md += `*${snippet.description}*\n\n`;
        }
        if (snippet.filename) {
          md += `\`${snippet.filename}\`:\n`;
        }
        md += `\`\`\`${snippet.language}\n${snippet.code}\n\`\`\`\n\n`;
      });
    }

    // Files to Create/Modify
    if (task.files && task.files.length > 0 && task.files[0] !== '[restructure directories]') {
      md += `**≡ƒôü Files to Create/Modify:**\n`;
      task.files.forEach(file => {
        md += `- [ ] \`${file}\`\n`;
      });
      md += '\n';
    }

    // Resources
    if (task.resources && task.resources.length > 0) {
      md += `**≡ƒôÜ Resources:**\n`;
      task.resources.forEach(resource => {
        md += `- ${resource}\n`;
      });
      md += '\n';
    }

    // Acceptance Criteria
    md += `**Γ£à Acceptance Criteria:**\n`;
    md += `- [ ] ${task.recommendation}\n`;
    md += `- [ ] Implementation tested and working\n`;
    md += `- [ ] Documentation updated if needed\n`;
    md += `- [ ] No regressions introduced\n`;
    md += `- [ ] Quality gates passing\n\n`;

    md += '---\n\n';

    return md;
  }

  private formatPriority(priority: string): string {
    const icons = {
      high: '≡ƒö┤ High',
      medium: '≡ƒƒí Medium',
      low: '≡ƒƒó Low'
    };
    return icons[priority as keyof typeof icons] || priority;
  }

  private generateImplementationGuidelines(): string {
    let md = '## ≡ƒ¢á∩╕Å Implementation Guidelines\n\n';
    md += '### Using Cursor Plan Mode\n\n';
    md += '1. Open Cursor Plan Mode (Cmd/Ctrl + Shift + P)\n';
    md += '2. Copy the relevant task from this plan\n';
    md += '3. Attach the [stack report](.devenv/stack-report.json) for context\n';
    md += '4. Execute the plan step by step, using Agent Mode for implementation\n\n';

    md += '### Task Completion Workflow\n\n';
    md += '1. **Read** the task description and acceptance criteria\n';
    md += '2. **Check** dependencies - complete prerequisite tasks first\n';
    md += '3. **Implement** using the provided code snippets as a starting point\n';
    md += '4. **Test** your changes locally\n';
    md += '5. **Update** relevant documentation\n';
    md += '6. **Run** quality gates (`npm test`, `npm run lint`, etc.)\n';
    md += '7. **Commit** with a descriptive message\n';
    md += '8. **Mark** the task as complete in this plan\n\n';

    md += '### Rollback Strategy\n\n';
    md += 'If any changes cause issues:\n\n';
    md += '1. Revert the specific commit: `git revert <commit-hash>`\n';
    md += '2. Document the issue in an issue tracker\n';
    md += '3. Adjust the approach based on lessons learned\n';
    md += '4. Re-implement with improvements\n\n';

    return md;
  }

  private generateSuccessMetrics(): string {
    let md = '## ≡ƒôê Success Metrics\n\n';
    md += 'Track your progress with these metrics:\n\n';
    md += '- [ ] All high-priority tasks completed\n';
    md += '- [ ] CI pipeline green (all quality gates passing)\n';
    md += '- [ ] Code coverage maintained or improved\n';
    md += '- [ ] No new security vulnerabilities\n';
    md += '- [ ] Team feedback collected and positive\n';
    md += '- [ ] Documentation updated and accurate\n';
    md += '- [ ] Gap analysis shows improvement on re-run\n\n';

    return md;
  }

  private generateResources(): string {
    let md = '## ≡ƒôÜ Additional Resources\n\n';
    md += '- [Stack Report](.devenv/stack-report.json) - Current project stack detection\n';
    md += '- [Gap Analysis](.devenv/gaps-report.md) - Detailed gap analysis\n';
    md += '- [Architecture Guide](../docs/ARCHITECTURE.md) - Project structure and design\n';
    md += '- [Best Practices](../docs/BEST-PRACTICES.md) - Technology-agnostic best practices\n';
    md += '- [Cursor Plan Integration](../docs/guides/cursor-plan-integration.md) - Plan mode guide\n';
    md += '- [DevEnvTemplate README](../README.md) - Template documentation\n\n';

    return md;
  }

  public async saveReport(planContent: string, filename: string = 'hardening-plan.md'): Promise<void> {
    const devenvDir = path.join(this.rootDir, '.devenv');
    await fs.mkdir(devenvDir, { recursive: true });
    const planPath = path.join(devenvDir, filename);
    await fs.writeFile(planPath, planContent, 'utf8');
    this.logger.info(`Hardening plan saved to ${planPath}`);
  }
}

// CLI execution
if (require.main === module) {
  const generator = new PlanGenerator();
  generator.generate()
    .then(async (plan) => {
      console.log(plan);
      await generator.saveReport(plan);
    })
    .catch((error) => {
      console.error('Plan generation failed:', error.message);
      process.exit(1);
    });
}

export default PlanGenerator;

#!/usr/bin/env node

/**
 * Stack Detector - CI-only utility
 *
 * Analyzes a repository to detect technology stack and configuration.
 * Used by .devenv to understand the current project setup.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { createLogger } from '../utils/logger';
import { createJsonParseError } from '../utils/error-helpers';
import type {
  StackReport,
  SecretsMetadata,
  ToolingFramework,
  EnvTemplateInfo,
  EnvLoaderInfo,
  DependencyAuditInfo
} from '../types/gaps';
import { STANDARD_CONDITIONAL_FILES, STANDARD_CORE_FILES } from './cursor-rules-adapter';

type DetectorMode = 'fast' | 'full';

interface StackDetectorOptions {
  rootDir?: string;
  quiet?: boolean;
  mode?: DetectorMode;
  debug?: boolean;
}

interface CachedFileOptions {
  allowMissing?: boolean;
}

type FullSecretsMetadata = {
  envTemplate: EnvTemplateInfo;
  envIgnored: boolean;
  envLoader: EnvLoaderInfo;
  dependencyAudit: DependencyAuditInfo;
};

const DEFAULT_IGNORED_DIRS = [
  'node_modules',
  '.git',
  '.hg',
  '.svn',
  '.idea',
  '.vscode',
  '.turbo',
  '.parcel-cache',
  '.cache',
  '.next',
  'build',
  'dist',
  'out',
  '.devenv',
  '.venv',
  'venv',
  '.pytest_cache',
  '.mypy_cache',
  '__pycache__',
  'library',
  'temp',
  'logs',
  'obj',
  'usersettings',
  'memorycaptures'
];

const FAST_ONLY_IGNORED_DIRS = [
  'coverage',
  '.nyc_output',
  'docs',
  'public',
  'tmp',
  'temp',
  'data',
  'datasets'
];

const WORKFLOW_SCAN_LIMIT = 50;
const FAST_WORKFLOW_SCAN_LIMIT = 12;

const args = process.argv.slice(2);
const jsonOutput = args.includes('--json');
const debugFlag = args.includes('--debug');
if (debugFlag && !process.env.LOG_LEVEL) {
  process.env.LOG_LEVEL = 'DEBUG';
}
const quietMode = jsonOutput || (!debugFlag && args.includes('--quiet'));
const modeArg = args.find(arg => arg.startsWith('--mode='));
const inlineFastFlag = args.includes('--fast') || args.includes('--shallow');
const requestedMode = modeArg ? modeArg.split('=')[1] : inlineFastFlag ? 'fast' : 'full';
const detectorMode: DetectorMode = requestedMode === 'fast' ? 'fast' : 'full';

const logger = createLogger({ context: 'stack-detector' });

const TECHNOLOGY_ALIASES: Record<string, string> = {
  python: 'Python',
  'python runtime': 'Python Runtime',
  pytorch: 'PyTorch',
  pychrono: 'PyChrono',
  numpy: 'NumPy',
  scipy: 'SciPy',
  pandas: 'Pandas',
  'scikit-learn': 'scikit-learn',
  sklearn: 'scikit-learn',
  matplotlib: 'Matplotlib',
  pytest: 'Pytest',
  black: 'Black',
  ruff: 'Ruff',
  mypy: 'Mypy',
  fastapi: 'FastAPI',
  django: 'Django',
  flask: 'Flask'
};

class StackDetector {
  private rootDir: string;
  private quiet: boolean;
  private projectManifest: Record<string, unknown> | null;
  private pyprojectContent: string | null;
  private requirementsContent: string | null;
  private packageJsonDeps: Record<string, string> | null;
  private stack: StackReport;
  private mode: DetectorMode;
  private fileCache: Map<string, string | null>;
  private ignoredDirectories: Set<string>;
  private workflowScanLimit: number;
  private debugMode: boolean;

  constructor(options: StackDetectorOptions = {}) {
    this.rootDir = options.rootDir || process.cwd();
    this.quiet = !!options.quiet;
    this.mode = options.mode || detectorMode;
    this.debugMode = !!options.debug;
    this.fileCache = new Map();
    this.ignoredDirectories = new Set(
      DEFAULT_IGNORED_DIRS.map(dir => dir.toLowerCase())
    );
    if (this.mode === 'fast') {
      FAST_ONLY_IGNORED_DIRS.forEach(dir => this.ignoredDirectories.add(dir.toLowerCase()));
    }
    this.workflowScanLimit = this.mode === 'fast'
      ? FAST_WORKFLOW_SCAN_LIMIT
      : WORKFLOW_SCAN_LIMIT;
    this.projectManifest = null;
    this.pyprojectContent = null;
    this.requirementsContent = null;
    this.packageJsonDeps = null;
    this.stack = {
      technologies: [],
      configurations: [],
      frameworks: {
        type: 'vanilla',
        version: null,
        dirs: []
      },
      tooling: {
        testing: { present: false, frameworks: [] },
        linting: { present: false, configs: [] },
        formatting: { present: false, configs: [] }
      },
      scripts: {
        detected: [],
        missing: []
      },
      files: {
        configs: [],
        key_patterns: []
      },
      quality: {
        linting: false,
        testing: false,
        typescript: false,
        security: false,
        formatting: false
      },
      ci: {
        present: false
      },
      secrets: {
        envTemplate: { present: false, files: [] },
        envIgnored: false,
        envLoader: { present: false, tools: [] },
        dependencyAudit: { present: false, tools: [] }
      },
      profiles: [],
      primaryProfile: null,
      languageProfile: 'agnostic',
      manifest: null,
      cursorRules: {
        present: false,
        existingFiles: [],
        coreFiles: [],
        conditionalFiles: [],
        projectSpecificFiles: [],
        needsIntegration: false
      }
    } as StackReport;

    this.logDebug('StackDetector initialized', {
      rootDir: this.rootDir,
      mode: this.mode
    });
  }

  private shouldSkipDirectory(name: string): boolean {
    return this.ignoredDirectories.has(name.toLowerCase());
  }

  private logDebug(message: string, meta: Record<string, unknown> = {}): void {
    if (this.debugMode) {
      logger.debug(message, meta);
    }
  }

  private async readFileCached(filePath: string, options: CachedFileOptions = {}): Promise<string | null> {
    const allowMissing = options.allowMissing !== false;
    const absPath = path.isAbsolute(filePath) ? filePath : path.join(this.rootDir, filePath);
    if (this.fileCache.has(absPath)) {
      return this.fileCache.get(absPath) ?? null;
    }
    try {
      const content = await fs.readFile(absPath, 'utf8');
      this.fileCache.set(absPath, content);
      return content;
    } catch (error: any) {
      if (!allowMissing || error.code !== 'ENOENT') {
        throw error;
      }
      this.fileCache.set(absPath, null);
      return null;
    }
  }

  private async readJsonFile(filePath: string): Promise<any> {
    const absPath = path.isAbsolute(filePath) ? filePath : path.join(this.rootDir, filePath);
    const content = await this.readFileCached(absPath, { allowMissing: false });
    if (content === null) {
      throw new Error(`File not found: ${absPath}`);
    }
    try {
      return JSON.parse(content);
    } catch (error: any) {
      if (error instanceof SyntaxError) {
        // Use improved error helper for better error messages
        throw createJsonParseError(error, absPath);
      }
      throw error;
    }
  }

  async detect(): Promise<StackReport> {
    this.logDebug('Starting stack detection run', { mode: this.mode });
    if (!this.quiet) {
      logger.info('≡ƒöì Analyzing repository stack...');
    }

    await this.loadProjectManifest();
    // Detect package managers and frameworks
    await this.detectPackageJson();
    await this.detectScripts();
    await this.detectTypeScript();
    await this.detectFrameworks();
    await this.detectExpress();
    await this.detectPrisma();
    await this.detectTailwind();
    await this.detectTesting();
    await this.detectLinting();
    await this.detectFormatting();
    await this.detectCI();
    await this.detectSecurity();
    await this.detectSecretsHygiene();
    await this.detectCursorRules();
    await this.detectUnrealProject();
    await this.detectUnityProject();
    this.assignProfiles();

    return this.stack;
  }

  /**
   * Detect Unreal Engine project marker (*.uproject at repo root) and populate stack hints.
   */
  private async detectUnrealProject(): Promise<void> {
    try {
      const entries = await fs.readdir(this.rootDir, { withFileTypes: true });
      const hasUProject = entries.some(
        e => e.isFile() && e.name.toLowerCase().endsWith('.uproject')
      );
      if (!hasUProject) {
        return;
      }
      this.stack.unrealProjectDetected = true;
      if (!this.stack.stackHints) {
        this.stack.stackHints = [];
      }
      this.stack.stackHints.push(
        'Unreal-like repo: .uproject at repository root. Ensure .cursor/rules/21-unreal-engine.mdc and 22-unreal-editor-ui.mdc are present; see docs/templates/unreal/README.md.'
      );
      this.addTechnology('Unreal Engine', {
        source: 'stack-detector',
        detector: 'uproject-root'
      });
    } catch (error: any) {
      if (error.code !== 'ENOENT') {
        this.logDebug('detectUnrealProject failed', { error: error.message });
      }
    }
  }

  /**
   * Detect Unity project via ProjectSettings/ProjectVersion.txt at repo root or one directory down (e.g. game/).
   */
  private async detectUnityProject(): Promise<void> {
    try {
      const versionRelPaths: string[] = [
        path.join('ProjectSettings', 'ProjectVersion.txt'),
      ];
      const entries = await fs.readdir(this.rootDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) {
          continue;
        }
        if (this.ignoredDirectories.has(entry.name.toLowerCase())) {
          continue;
        }
        versionRelPaths.push(path.join(entry.name, 'ProjectSettings', 'ProjectVersion.txt'));
      }

      let foundRel: string | null = null;
      for (const rel of versionRelPaths) {
        try {
          await fs.access(path.join(this.rootDir, rel));
          foundRel = rel;
          break;
        } catch {
          // keep looking
        }
      }
      if (!foundRel) {
        return;
      }

      this.stack.unityProjectDetected = true;
      if (!this.stack.stackHints) {
        this.stack.stackHints = [];
      }
      this.stack.stackHints.push(
        `Unity-like repo: ${foundRel.replace(/\\/g, '/')}. Ensure .cursor/rules/23-unity-csharp.mdc is present; see docs/templates/unity/README.md.`
      );
      this.addTechnology('Unity', {
        source: 'stack-detector',
        detector: 'project-version'
      });
    } catch (error: any) {
      if (error.code !== 'ENOENT') {
        this.logDebug('detectUnityProject failed', { error: error.message });
      }
    }
  }

