// scripts/utils/cache.ts

import { promises as fs } from 'fs';
import path from 'path';
import { createHash } from 'crypto';
import { createLogger, Logger } from './logger';

const logger = createLogger({ context: 'cache' });

export interface CacheEntry {
  hash: string;
  timestamp: number;
  data: any;
  ttl?: number;
}

export interface CacheOptions {
  cacheDir?: string;
  ttl?: number; // Time to live in milliseconds
  maxSize?: number; // Maximum cache size in bytes
}

export class FileCache {
  private cacheDir: string;
  private ttl: number;
  private maxSize: number;
  private memoryCache: Map<string, CacheEntry>;
  private logger: Logger;

  constructor(options: CacheOptions = {}) {
    this.cacheDir = options.cacheDir || path.join(process.cwd(), '.cache');
    this.ttl = options.ttl || 24 * 60 * 60 * 1000; // 24 hours default
    this.maxSize = options.maxSize || 100 * 1024 * 1024; // 100MB default
    this.memoryCache = new Map();
    this.logger = createLogger({ context: 'FileCache' });
  }

  /**
   * Initialize cache directory
   */
  public async init(): Promise<void> {
    try {
      await fs.mkdir(this.cacheDir, { recursive: true });
      this.logger.debug('Cache directory initialized', { cacheDir: this.cacheDir });
    } catch (error: any) {
      this.logger.warn('Failed to create cache directory', { error: error.message });
    }
  }

  /**
   * Generate hash for file content
   */
  public generateHash(content: string | Buffer): string {
    return createHash('sha256').update(content).digest('hex');
  }

  /**
   * Generate cache key from file path and content hash
   */
  private getCacheKey(filePath: string, contentHash: string): string {
    const normalized = path.normalize(filePath).replace(/\\/g, '/');
    return `${createHash('sha256').update(normalized).digest('hex')}-${contentHash}`;
  }

  /**
   * Get cached entry
   */
  public async get(filePath: string, contentHash: string): Promise<any | null> {
    const cacheKey = this.getCacheKey(filePath, contentHash);

    // Check memory cache first
    const memEntry = this.memoryCache.get(cacheKey);
    if (memEntry) {
      if (this.isValid(memEntry)) {
        this.logger.debug('Memory cache hit', { filePath, cacheKey });
        return memEntry.data;
      } else {
        this.memoryCache.delete(cacheKey);
      }
    }

    // Check disk cache
    try {
      const cachePath = path.join(this.cacheDir, `${cacheKey}.json`);
      const cacheData = await fs.readFile(cachePath, 'utf8');
      const entry: CacheEntry = JSON.parse(cacheData);

      if (this.isValid(entry)) {
        // Restore to memory cache
        this.memoryCache.set(cacheKey, entry);
        this.logger.debug('Disk cache hit', { filePath, cacheKey });
        return entry.data;
      } else {
        // Expired, delete it
        await fs.unlink(cachePath).catch(() => {});
        this.logger.debug('Cache entry expired', { filePath, cacheKey });
      }
    } catch (error) {
      // Cache miss
      this.logger.debug('Cache miss', { filePath, cacheKey });
    }

    return null;
  }

  /**
   * Set cache entry
   */
  public async set(filePath: string, contentHash: string, data: any, ttl?: number): Promise<void> {
    const cacheKey = this.getCacheKey(filePath, contentHash);
    const entry: CacheEntry = {
      hash: contentHash,
      timestamp: Date.now(),
      data,
      ttl: ttl || this.ttl
    };

    // Store in memory cache
    this.memoryCache.set(cacheKey, entry);

    // Store in disk cache
    try {
      const cachePath = path.join(this.cacheDir, `${cacheKey}.json`);
      await fs.writeFile(cachePath, JSON.stringify(entry), 'utf8');
      this.logger.debug('Cache entry stored', { filePath, cacheKey });
    } catch (error: any) {
      this.logger.warn('Failed to write cache entry', { error: error.message, filePath });
    }
  }

  /**
   * Check if cache entry is still valid
   */
  private isValid(entry: CacheEntry): boolean {
    const age = Date.now() - entry.timestamp;
    const ttl = entry.ttl || this.ttl;
    return age < ttl;
  }

  /**
   * Clear all cache entries
   */
  public async clear(): Promise<void> {
    this.memoryCache.clear();
    
    try {
      const files = await fs.readdir(this.cacheDir);
      await Promise.all(
        files.map(file => fs.unlink(path.join(this.cacheDir, file)).catch(() => {}))
      );
      this.logger.info('Cache cleared');
    } catch (error: any) {
      this.logger.warn('Failed to clear cache', { error: error.message });
    }
  }

  /**
   * Get cache statistics
   */
  public async getStats(): Promise<{ entries: number; size: number; memoryEntries: number }> {
    let entries = 0;
    let size = 0;

    try {
      const files = await fs.readdir(this.cacheDir);
      entries = files.length;
      
      const sizes = await Promise.all(
        files.map(async file => {
          try {
            const stat = await fs.stat(path.join(this.cacheDir, file));
            return stat.size;
          } catch {
            return 0;
          }
        })
      );
      
      size = sizes.reduce((sum, s) => sum + s, 0);
    } catch (error) {
      // Directory doesn't exist or can't be read
    }

    return {
      entries,
      size,
      memoryEntries: this.memoryCache.size
    };
  }

  /**
   * Prune old cache entries
   */
  public async prune(): Promise<number> {
    let pruned = 0;

    // Prune memory cache
    for (const [key, entry] of this.memoryCache.entries()) {
      if (!this.isValid(entry)) {
        this.memoryCache.delete(key);
        pruned++;
      }
    }

    // Prune disk cache
    try {
      const files = await fs.readdir(this.cacheDir);
      
      for (const file of files) {
        try {
          const cachePath = path.join(this.cacheDir, file);
          const content = await fs.readFile(cachePath, 'utf8');
          const entry: CacheEntry = JSON.parse(content);
          
          if (!this.isValid(entry)) {
            await fs.unlink(cachePath);
            pruned++;
          }
        } catch {
          // Invalid cache file, delete it
          await fs.unlink(path.join(this.cacheDir, file)).catch(() => {});
          pruned++;
        }
      }
    } catch (error: any) {
      this.logger.warn('Failed to prune cache', { error: error.message });
    }

    if (pruned > 0) {
      this.logger.info(`Pruned ${pruned} expired cache entries`);
    }

    return pruned;
  }
}

/**
 * Configuration cache for cleanup engine
 */
export class ConfigCache {
  private cache: Map<string, { config: any; hash: string; timestamp: number }>;
  private ttl: number;
  private logger: Logger;

  constructor(ttl: number = 60 * 60 * 1000) { // 1 hour default
    this.cache = new Map();
    this.ttl = ttl;
    this.logger = createLogger({ context: 'ConfigCache' });
  }

  /**
   * Get cached configuration
   */
  public get(configPath: string, currentHash: string): any | null {
    const entry = this.cache.get(configPath);
    
    if (!entry) {
      this.logger.debug('Config cache miss', { configPath });
      return null;
    }

    // Check if hash matches
    if (entry.hash !== currentHash) {
      this.cache.delete(configPath);
      this.logger.debug('Config cache invalidated (hash mismatch)', { configPath });
      return null;
    }

    // Check if expired
    const age = Date.now() - entry.timestamp;
    if (age > this.ttl) {
      this.cache.delete(configPath);
      this.logger.debug('Config cache expired', { configPath });
      return null;
    }

    this.logger.debug('Config cache hit', { configPath });
    return entry.config;
  }

  /**
   * Set cached configuration
   */
  public set(configPath: string, config: any, hash: string): void {
    this.cache.set(configPath, {
      config,
      hash,
      timestamp: Date.now()
    });
    this.logger.debug('Config cached', { configPath });
  }

  /**
   * Clear cache
   */
  public clear(): void {
    this.cache.clear();
    this.logger.info('Config cache cleared');
  }

  /**
   * Get cache size
   */
  public size(): number {
    return this.cache.size;
  }
}

/**
 * Documentation Organizer Utility
 * 
 * Automatically detects and organizes markdown files into appropriate directories
 * based on configurable rules to prevent documentation clutter in project root.
 */

import { promises as fs } from 'fs';
import * as path from 'path';
import yaml from 'yaml';
import { resolveConfigPath, resolveProjectRoot } from './path-resolver';
import { execSync } from 'child_process';

/**
 * Configuration for documentation organization
 */
export interface DocsOrganizationConfig {
  rootExceptions: string[];
  directoryRules: {
    [key: string]: {
      patterns: string[];
      target: string;
    };
  };
  defaultTarget: string;
}

/**
 * Result of organizing documentation
 */
export interface OrganizeResult {
  success: boolean;
  filesToMove: FileMove[];
  conflicts: Conflict[];
  errors: string[];
  dryRun: boolean;
}

/**
 * Represents a file that should be moved
 */
export interface FileMove {
  source: string;
  target: string;
  targetDir: string;
  reason: string;
}

/**
 * Represents a conflict (target file already exists)
 */
export interface Conflict {
  source: string;
  target: string;
  message: string;
}

/**
 * Validation result
 */
export interface ValidationResult {
  needsOrganization: boolean;
  misplacedFiles: string[];
  totalFiles: number;
}

/**
 * Load documentation organization configuration
 */
export async function loadDocsConfig(projectRoot: string): Promise<DocsOrganizationConfig> {
  // Try project-specific config first (.devenv/config/ or project root)
  const projectConfigPath = resolveConfigPath('docs-organization.yaml', projectRoot);

  // Try .devenv default config
  const devenvRoot = path.resolve(__dirname, '../../');
  const defaultConfigPath = path.join(devenvRoot, 'config', 'docs-organization.yaml');

  let configPath: string;
  let configContent: string;

  // Try project config first
  try {
    await fs.access(projectConfigPath);
    configPath = projectConfigPath;
    configContent = await fs.readFile(configPath, 'utf8');
  } catch {
    // Fallback to default config
    try {
      configPath = defaultConfigPath;
      configContent = await fs.readFile(configPath, 'utf8');
    } catch (error: any) {
      throw new Error(`Failed to load docs-organization.yaml: ${error.message}`);
    }
  }

  const config = yaml.parse(configContent) as DocsOrganizationConfig;

  // Validate config structure
  if (!config.rootExceptions || !Array.isArray(config.rootExceptions)) {
    throw new Error('Invalid config: rootExceptions must be an array');
  }

  if (!config.directoryRules || typeof config.directoryRules !== 'object') {
    throw new Error('Invalid config: directoryRules must be an object');
  }

  if (!config.defaultTarget || typeof config.defaultTarget !== 'string') {
    throw new Error('Invalid config: defaultTarget must be a string');
  }

  return config;
}

/**
 * Check if a filename matches a pattern (supports wildcards)
 * @internal
 */
export function matchesPattern(filename: string, pattern: string): boolean {
  // Convert pattern to regex
  const regexPattern = pattern
    .replace(/\*/g, '.*')
    .replace(/\?/g, '.');

  const regex = new RegExp(`^${regexPattern}$`, 'i');
  return regex.test(filename);
}

/**
 * Determine target directory for a markdown file
 */
export function determineTargetDirectory(
  filename: string,
  config: DocsOrganizationConfig,
  projectRoot: string
): { target: string; reason: string } {
  // Check if file is in root exceptions
  if (config.rootExceptions.includes(filename)) {
    return { target: projectRoot, reason: 'Root exception' };
  }

  // Check directory rules
  for (const [ruleName, rule] of Object.entries(config.directoryRules)) {
    for (const pattern of rule.patterns) {
      if (matchesPattern(filename, pattern)) {
        const targetDir = path.join(projectRoot, rule.target);
        return { target: targetDir, reason: `Matches ${ruleName} rule (${pattern})` };
      }
    }
  }

  // Default target
  const defaultDir = path.join(projectRoot, config.defaultTarget);
  return { target: defaultDir, reason: 'Default target' };
}

/**
 * Detect markdown files in project root that should be moved
 */
export async function detectMisplacedDocs(projectRoot: string): Promise<string[]> {
  const misplaced: string[] = [];

  try {
    const files = await fs.readdir(projectRoot);
    const config = await loadDocsConfig(projectRoot);

    for (const file of files) {
      // Only check .md files
      if (!file.endsWith('.md')) {
        continue;
      }

      const filePath = path.join(projectRoot, file);
      const stats = await fs.stat(filePath);

      // Only check files (not directories)
      if (!stats.isFile()) {
        continue;
      }

      // Check if file should be moved
      const { target } = determineTargetDirectory(file, config, projectRoot);

      // If target is not project root, file should be moved
      if (target !== projectRoot) {
        misplaced.push(file);
      }
    }
  } catch (error: any) {
    throw new Error(`Failed to detect misplaced docs: ${error.message}`);
  }

  return misplaced;
}

/**
 * Check if a file is tracked by git
 */
function isGitTracked(filePath: string, projectRoot: string): boolean {
  try {
    const relativePath = path.relative(projectRoot, filePath).replace(/\\/g, '/');
    execSync(`git ls-files --error-unmatch "${relativePath}"`, {
      cwd: projectRoot,
      stdio: 'ignore'
    });
    return true;
  } catch {
    return false;
  }
}

/**
 * Organize documentation files
 */
export async function organizeDocumentation(
  projectRoot: string,
  dryRun: boolean = true
): Promise<OrganizeResult> {
  const result: OrganizeResult = {
    success: true,
    filesToMove: [],
    conflicts: [],
    errors: [],
    dryRun
  };

  try {
    const config = await loadDocsConfig(projectRoot);
    const misplacedFiles = await detectMisplacedDocs(projectRoot);

    for (const filename of misplacedFiles) {
      const sourcePath = path.join(projectRoot, filename);
      const { target: targetDir, reason } = determineTargetDirectory(filename, config, projectRoot);
      const targetPath = path.join(targetDir, filename);

      // Check if target directory exists, create if needed
      if (!dryRun) {
        try {
          await fs.access(targetDir);
        } catch {
          await fs.mkdir(targetDir, { recursive: true });
        }
      }

      // Check for conflicts
      try {
        await fs.access(targetPath);
        result.conflicts.push({
          source: sourcePath,
          target: targetPath,
          message: `Target file already exists: ${targetPath}`
        });
        continue;
      } catch {
        // File doesn't exist, good to proceed
      }

      result.filesToMove.push({
        source: sourcePath,
        target: targetPath,
        targetDir,
        reason
      });

      // Perform move if not dry run
      if (!dryRun) {
        try {
          // Check if file is git-tracked
          const isTracked = isGitTracked(sourcePath, projectRoot);

          // Move file
          await fs.rename(sourcePath, targetPath);

          // Stage move in git if tracked
          if (isTracked) {
            try {
              execSync(`git add "${path.relative(projectRoot, targetPath).replace(/\\/g, '/')}"`, {
                cwd: projectRoot,
                stdio: 'ignore'
              });
              execSync(`git add "${path.relative(projectRoot, sourcePath).replace(/\\/g, '/')}"`, {
                cwd: projectRoot,
                stdio: 'ignore'
              });
            } catch (gitError) {
              // Git staging failed, but file was moved
              result.errors.push(`Failed to stage git move for ${filename}: ${gitError}`);
            }
          }
        } catch (moveError: any) {
          result.errors.push(`Failed to move ${filename}: ${moveError.message}`);
          result.success = false;
        }
      }
    }
  } catch (error: any) {
    result.errors.push(`Organization failed: ${error.message}`);
    result.success = false;
  }

  return result;
}

/**
 * Validate if organization is needed
 */
export async function validateOrganization(projectRoot: string): Promise<ValidationResult> {
  try {
    const misplacedFiles = await detectMisplacedDocs(projectRoot);
    const files = await fs.readdir(projectRoot);
    const mdFiles = files.filter(f => f.endsWith('.md'));

    return {
      needsOrganization: misplacedFiles.length > 0,
      misplacedFiles,
      totalFiles: mdFiles.length
    };
  } catch (error: any) {
    throw new Error(`Validation failed: ${error.message}`);
  }
}

/**
 * Environment Variable Validation Utilities
 * 
 * Provides framework-agnostic utilities for:
 * - Environment variable presence checks
 * - Format validation (base64, hex, etc.)
 * - Validation with helpful error messages
 * - Multiple variable checks
 */

import { validateBase64Key, verifyKeyFormat } from './crypto-helpers';

export interface EnvVarOptions {
  hint?: string;
  validator?: (value: string) => boolean;
  errorMessage?: string;
  docs?: string;
}

/**
 * Require an environment variable to be set
 * 
 * @param name - Environment variable name
 * @param options - Optional configuration (hint, validator, error message, docs)
 * @returns The environment variable value
 * @throws Error if variable is not set or validation fails
 * 
 * @example
 * ```typescript
 * // Simple check
 * const apiKey = requireEnvVar('API_KEY');
 * 
 * // With hint
 * const dbUrl = requireEnvVar('DATABASE_URL', {
 *   hint: 'Set DATABASE_URL in your .env file or export it in your shell'
 * });
 * 
 * // With validation
 * const encryptionKey = requireEnvVar('ENCRYPTION_KEY', {
 *   validator: (val) => verifyKeyFormat(val, 32),
 *   errorMessage: 'ENCRYPTION_KEY must be a valid 32-byte base64-encoded key'
 * });
 * ```
 */
export function requireEnvVar(
  name: string,
  options: EnvVarOptions = {}
): string {
  const value = process.env[name];

  if (!value) {
    const hint = options.hint || `Set ${name} in your environment or .env file`;
    const docs = options.docs ? `\nSee ${options.docs} for more information.` : '';

    throw new Error(
      `Environment variable ${name} is required but not set.\n` +
      `Hint: ${hint}${docs}`
    );
  }

  // Run validator if provided
  if (options.validator) {
    const isValid = options.validator(value);
    if (!isValid) {
      const errorMessage = options.errorMessage || 
        `Environment variable ${name} failed validation`;
      const hint = options.hint || `Check the format of ${name}`;
      const docs = options.docs ? `\nSee ${options.docs} for more information.` : '';

      throw new Error(
        `${errorMessage}.\n` +
        `Hint: ${hint}${docs}`
      );
    }
  }

  return value;
}

/**
 * Validate environment variable format
 * 
 * @param name - Environment variable name
 * @param validator - Validation function
 * @param errorMessage - Custom error message if validation fails
 * @returns The environment variable value
 * @throws Error if validation fails
 * 
 * @example
 * ```typescript
 * const key = validateEnvVar(
 *   'ENCRYPTION_KEY',
 *   (val) => verifyKeyFormat(val, 32),
 *   'ENCRYPTION_KEY must be a valid 32-byte base64-encoded key'
 * );
 * ```
 */
export function validateEnvVar(
  name: string,
  validator: (value: string) => boolean,
  errorMessage: string
): string {
  const value = process.env[name];

  if (!value) {
    throw new Error(`Environment variable ${name} is not set`);
  }

  if (!validator(value)) {
    throw new Error(errorMessage);
  }

  return value;
}

/**
 * Check multiple required environment variables
 * 
 * @param vars - Array of variable names or objects with name and options
 * @returns Record of variable names to values
 * @throws Error if any variable is missing or validation fails
 * 
 * @example
 * ```typescript
 * // Simple check
 * const env = requireEnvVars(['API_KEY', 'DATABASE_URL']);
 * 
 * // With validation
 * const env = requireEnvVars([
 *   'API_KEY',
 *   { name: 'ENCRYPTION_KEY', options: { validator: (v) => verifyKeyFormat(v, 32) } }
 * ]);
 * ```
 */
export function requireEnvVars(
  vars: (string | { name: string; options?: EnvVarOptions })[]
): Record<string, string> {
  const result: Record<string, string> = {};
  const errors: string[] = [];

  for (const varDef of vars) {
    const name = typeof varDef === 'string' ? varDef : varDef.name;
    const options = typeof varDef === 'string' ? {} : (varDef.options || {});

    try {
      result[name] = requireEnvVar(name, options);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      errors.push(errorMessage);
    }
  }

  if (errors.length > 0) {
    throw new Error(
      `Missing or invalid environment variables:\n${errors.join('\n')}`
    );
  }

  return result;
}

/**
 * Check if environment variable is set (non-throwing)
 * 
 * @param name - Environment variable name
 * @returns True if variable is set and non-empty
 * 
 * @example
 * ```typescript
 * if (hasEnvVar('DEBUG')) {
 *   console.log('Debug mode enabled');
 * }
 * ```
 */
export function hasEnvVar(name: string): boolean {
  const value = process.env[name];
  return value !== undefined && value !== '';
}

/**
 * Get environment variable with default value
 * 
 * @param name - Environment variable name
 * @param defaultValue - Default value if variable is not set
 * @returns Environment variable value or default
 * 
 * @example
 * ```typescript
 * const port = getEnvVar('PORT', '3000');
 * ```
 */
export function getEnvVar(name: string, defaultValue: string): string {
  return process.env[name] || defaultValue;
}

/**
 * Validate base64-encoded encryption key environment variable
 * 
 * @param name - Environment variable name
 * @param expectedBytes - Expected number of bytes (default: 32)
 * @returns The validated key
 * @throws Error if key is missing or invalid
 * 
 * @example
 * ```typescript
 * const key = requireEncryptionKey('ENCRYPTION_KEY', 32);
 * ```
 */
export function requireEncryptionKey(
  name: string,
  expectedBytes: number = 32
): string {
  return requireEnvVar(name, {
    validator: (value) => verifyKeyFormat(value, expectedBytes),
    errorMessage: `${name} must be a valid ${expectedBytes}-byte base64-encoded key`,
    hint: `Generate a key using: node dist/scripts/tools/generate-key.js --length ${expectedBytes}`,
    docs: 'docs/BEST-PRACTICES.md#encryption-key-generation'
  });
}

/**
 * Check if all required environment variables are set
 * 
 * @param vars - Array of variable names
 * @returns Array of missing variable names
 * 
 * @example
 * ```typescript
 * const missing = checkMissingEnvVars(['API_KEY', 'DATABASE_URL']);
 * if (missing.length > 0) {
 *   console.error('Missing variables:', missing);
 * }
 * ```
 */
export function checkMissingEnvVars(vars: string[]): string[] {
  return vars.filter(name => !hasEnvVar(name));
}

// scripts/utils/parallel.ts

import { createLogger, Logger } from './logger';

const logger = createLogger({ context: 'parallel' });

export interface ParallelOptions {
  concurrency: number;
  onProgress?: (completed: number, total: number) => void;
}

export interface ParallelResult<R> {
  results: R[];
  errors: Array<{ item: any; error: Error }>;
}

/**
 * Execute async operations in parallel with concurrency control
 * 
 * @param items - Array of items to process
 * @param worker - Async function to process each item
 * @param options - Parallel execution options
 * @returns Promise resolving to results and errors
 */
export async function parallel<T, R>(
  items: T[],
  worker: (item: T) => Promise<R>,
  options: ParallelOptions
): Promise<ParallelResult<R>> {
  const { concurrency, onProgress } = options;
  const results: R[] = [];
  const errors: Array<{ item: T; error: Error }> = [];

  if (items.length === 0) {
    return { results, errors };
  }

  logger.debug(`Starting parallel execution: ${items.length} items, concurrency ${concurrency}`);

  let completed = 0;
  let index = 0;

  // Create a pool of workers
  const workers = Array(Math.min(concurrency, items.length))
    .fill(null)
    .map(async () => {
      while (index < items.length) {
        const currentIndex = index++;
        const item = items[currentIndex];

        try {
          const result = await worker(item);
          results[currentIndex] = result;
        } catch (error) {
          logger.warn(`Worker failed for item at index ${currentIndex}`, { error: (error as Error).message });
          errors.push({ item, error: error as Error });
          // Store undefined for failed items to maintain index alignment
          results[currentIndex] = undefined as any;
        }

        completed++;
        if (onProgress) {
          onProgress(completed, items.length);
        }
      }
    });

  // Wait for all workers to complete
  await Promise.all(workers);

  logger.debug(`Parallel execution completed: ${results.length} results, ${errors.length} errors`);

  return { results, errors };
}

/**
 * Execute async operations in batches with concurrency control
 * Alternative approach that processes in explicit batches
 * 
 * @param items - Array of items to process
 * @param worker - Async function to process each item
 * @param options - Parallel execution options
 * @returns Promise resolving to results and errors
 */
export async function parallelBatch<T, R>(
  items: T[],
  worker: (item: T) => Promise<R>,
  options: ParallelOptions
): Promise<ParallelResult<R>> {
  const { concurrency, onProgress } = options;
  const results: R[] = [];
  const errors: Array<{ item: T; error: Error }> = [];

  if (items.length === 0) {
    return { results, errors };
  }

  logger.debug(`Starting batch parallel execution: ${items.length} items, batch size ${concurrency}`);

  let completed = 0;

  // Process in batches
  for (let i = 0; i < items.length; i += concurrency) {
    const batch = items.slice(i, i + concurrency);
    const batchPromises = batch.map(async (item, batchIndex) => {
      const globalIndex = i + batchIndex;
      try {
        const result = await worker(item);
        return { index: globalIndex, result, error: null };
      } catch (error) {
        logger.warn(`Batch worker failed for item at index ${globalIndex}`, { error: (error as Error).message });
        return { index: globalIndex, result: undefined as any, error: { item, error: error as Error } };
      }
    });

    const batchResults = await Promise.all(batchPromises);

    // Collect results and errors
    for (const { index, result, error } of batchResults) {
      if (error) {
        errors.push(error);
      }
      results[index] = result;
      completed++;
      if (onProgress) {
        onProgress(completed, items.length);
      }
    }
  }

  logger.debug(`Batch parallel execution completed: ${results.length} results, ${errors.length} errors`);

  return { results, errors };
}

/**
 * Calculate optimal concurrency based on system resources and workload
 * 
 * @param itemCount - Number of items to process
 * @param cpuCount - Number of CPU cores available
 * @param ioIntensive - Whether the workload is I/O intensive (true) or CPU intensive (false)
 * @returns Recommended concurrency level
 */
export function calculateOptimalConcurrency(
  itemCount: number,
  cpuCount: number,
  ioIntensive: boolean = true
): number {
  if (itemCount === 0) return 1;

  // For I/O intensive tasks, use more concurrency (2x CPU count)
  // For CPU intensive tasks, use CPU count
  const baseConcurrency = ioIntensive ? cpuCount * 2 : cpuCount;

  // Don't exceed item count
  return Math.min(baseConcurrency, itemCount);
}

/**
 * Cross-platform shell command execution utility
 * Handles both bash/zsh and PowerShell command syntax
 */

import { execSync, ExecSyncOptions } from 'child_process';
import * as os from 'os';

export type ShellType = 'bash' | 'powershell' | 'unknown';

/**
 * Detect the current shell type
 */
export function detectShell(): ShellType {
  const platform = os.platform();
  const shell = process.env.SHELL || process.env.COMSPEC || '';

  if (platform === 'win32') {
    // Check if PowerShell
    if (shell.toLowerCase().includes('powershell') || shell.toLowerCase().includes('pwsh')) {
      return 'powershell';
    }
    // Default to PowerShell on Windows
    return 'powershell';
  }

  // Unix-like systems
  if (shell.includes('bash') || shell.includes('zsh') || shell.includes('sh')) {
    return 'bash';
  }

  return 'unknown';
}

/**
 * Execute a command with cross-platform compatibility
 * Automatically handles command chaining for different shells
 */
export function runCommand(
  command: string,
  options: ExecSyncOptions & { shellType?: ShellType } = {}
): string {
  const shellType = options.shellType || detectShell();
  const { shellType: _, ...execOptions } = options;

  // Normalize command for the detected shell
  let normalizedCommand = command;
  let shellPath: string | undefined;

  if (shellType === 'powershell') {
    // Replace && with ; for PowerShell
    normalizedCommand = command.replace(/&&/g, ';');
    // Use PowerShell as shell (Windows only)
    if (process.platform === 'win32') {
      shellPath = 'powershell.exe';
    }
  } else {
    // Use bash/sh for Unix-like systems
    if (process.platform !== 'win32') {
      shellPath = '/bin/bash';
    }
  }

  try {
    const execOpts: ExecSyncOptions = {
      encoding: 'utf8',
      stdio: 'pipe',
      ...execOptions,
    };
    
    // Add shell option if specified (Node.js supports this)
    if (shellPath) {
      (execOpts as any).shell = shellPath;
    }
    
    return execSync(normalizedCommand, execOpts).toString();
  } catch (error: any) {
    throw new Error(
      `Command failed: ${normalizedCommand}\n` +
      `Shell: ${shellType}\n` +
      `Error: ${error.message}`
    );
  }
}

/**
 * Chain multiple commands with appropriate separator
 */
export function chainCommands(commands: string[], shell?: ShellType): string {
  const shellType = shell || detectShell();
  const separator = shellType === 'powershell' ? ';' : '&&';
  return commands.join(` ${separator} `);
}

/**
 * Check if a command exists in PATH
 */
export function commandExists(command: string): boolean {
  try {
    if (detectShell() === 'powershell') {
      runCommand(`Get-Command ${command} -ErrorAction SilentlyContinue`, { shellType: 'powershell' });
    } else {
      runCommand(`which ${command}`, { shellType: 'bash' });
    }
    return true;
  } catch {
    return false;
  }
}

/**
 * Get platform-specific path separator
 */
export function getPathSeparator(): string {
  return os.platform() === 'win32' ? '\\' : '/';
}

/**
 * Normalize path for current platform
 */
export function normalizePath(path: string): string {
  const separator = getPathSeparator();
  return path.replace(/[/\\]/g, separator);
}

/**
 * Verification Utilities
 * 
 * Provides framework-agnostic utilities for:
 * - Pre-commit verification checks
 * - Pre-deployment verification checks
 * - Environment setup verification
 * - Framework-agnostic verification patterns
 */

import * as fs from 'fs';
import * as path from 'path';
import { hasEnvVar, checkMissingEnvVars, requireEncryptionKey } from './env-validator';
import { verifyKeyFormat } from './crypto-helpers';
import { createActionableError } from './error-helpers';

export interface VerificationResult {
  passed: boolean;
  errors: string[];
  warnings?: string[];
}

/**
 * Run pre-commit verification checks
 * 
 * @param projectRoot - Root directory of the project
 * @returns Verification result with errors if any
 * 
 * @example
 * ```typescript
 * const result = await verifyPreCommit('/path/to/project');
 * if (!result.passed) {
 *   console.error('Pre-commit checks failed:', result.errors);
 * }
 * ```
 */
export async function verifyPreCommit(projectRoot: string): Promise<VerificationResult> {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Check for .env.example
  const envExamplePath = path.join(projectRoot, '.env.example');
  if (!fs.existsSync(envExamplePath)) {
    warnings.push('.env.example not found - consider adding it for documentation');
  }

  // Check for .gitignore containing .env
  const gitignorePath = path.join(projectRoot, '.gitignore');
  if (fs.existsSync(gitignorePath)) {
    const gitignoreContent = fs.readFileSync(gitignorePath, 'utf-8');
    if (!gitignoreContent.includes('.env')) {
      errors.push('.gitignore does not include .env - secrets may be committed');
    }
  } else {
    warnings.push('.gitignore not found');
  }

  // Check for syntax errors in common config files
  const configFiles = ['package.json', 'tsconfig.json', 'pyproject.toml'];
  for (const configFile of configFiles) {
    const configPath = path.join(projectRoot, configFile);
    if (fs.existsSync(configPath)) {
      try {
        const content = fs.readFileSync(configPath, 'utf-8');
        if (configFile.endsWith('.json')) {
          JSON.parse(content);
        }
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        errors.push(`Invalid JSON in ${configFile}: ${errorMessage}`);
      }
    }
  }

  return {
    passed: errors.length === 0,
    errors,
    warnings: warnings.length > 0 ? warnings : undefined
  };
}

/**
 * Run pre-deployment verification checks
 * 
 * @param projectRoot - Root directory of the project
 * @returns Verification result with errors if any
 * 
 * @example
 * ```typescript
 * const result = await verifyPreDeployment('/path/to/project');
 * if (!result.passed) {
 *   console.error('Pre-deployment checks failed:', result.errors);
 *   process.exit(1);
 * }
 * ```
 */
export async function verifyPreDeployment(projectRoot: string): Promise<VerificationResult> {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Check for required environment variables (if .env.example exists)
  const envExamplePath = path.join(projectRoot, '.env.example');
  if (fs.existsSync(envExamplePath)) {
    const envExampleContent = fs.readFileSync(envExamplePath, 'utf-8');
    const requiredVars: string[] = [];

    // Extract variable names from .env.example
    const lines = envExampleContent.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
        const varName = trimmed.split('=')[0].trim();
        if (varName) {
          requiredVars.push(varName);
        }
      }
    }

    // Check for encryption keys specifically
    const encryptionKeyVars = requiredVars.filter(v => 
      v.toLowerCase().includes('key') || 
      v.toLowerCase().includes('secret') ||
      v.toLowerCase().includes('encryption')
    );

    for (const varName of encryptionKeyVars) {
      if (!hasEnvVar(varName)) {
        errors.push(`Required environment variable ${varName} is not set`);
      } else {
        // Validate encryption key format if it looks like one
        const value = process.env[varName];
        if (value && value.length >= 40) {
          // Likely a base64 key, validate it
          try {
            if (!verifyKeyFormat(value, 32) && !verifyKeyFormat(value, 64)) {
              warnings.push(`${varName} may have invalid format - verify it's a valid base64 key`);
            }
          } catch {
            // Ignore validation errors for warnings
          }
        }
      }
    }
  }

  // Check for common security issues
  const packageJsonPath = path.join(projectRoot, 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    try {
      const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf-8'));

      // Check for hardcoded secrets in scripts (basic check)
      const scripts = packageJson.scripts || {};
      for (const [scriptName, scriptContent] of Object.entries(scripts)) {
        const content = String(scriptContent);
        if (content.includes('password') || content.includes('secret') || content.includes('key=')) {
          warnings.push(`Script ${scriptName} may contain hardcoded secrets`);
        }
      }
    } catch {
      // Ignore parse errors (handled in pre-commit)
    }
  }

  return {
    passed: errors.length === 0,
    errors,
    warnings: warnings.length > 0 ? warnings : undefined
  };
}

/**
 * Verify environment setup
 * 
 * @param projectRoot - Root directory of the project
 * @returns Verification result with errors if any
 * 
 * @example
 * ```typescript
 * const result = await verifyEnvironment('/path/to/project');
 * if (!result.passed) {
 *   console.error('Environment setup incomplete:', result.errors);
 * }
 * ```
 */
export async function verifyEnvironment(projectRoot: string): Promise<VerificationResult> {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Check for .env file
  const envPath = path.join(projectRoot, '.env');
  if (!fs.existsSync(envPath)) {
    warnings.push('.env file not found - environment variables may not be loaded');
  }

  // Check for .env.example
  const envExamplePath = path.join(projectRoot, '.env.example');
  if (!fs.existsSync(envExamplePath)) {
    warnings.push('.env.example not found - no template for environment variables');
  }

  // Check for required files based on project type
  const packageJsonPath = path.join(projectRoot, 'package.json');
  const pyprojectTomlPath = path.join(projectRoot, 'pyproject.toml');

  if (fs.existsSync(packageJsonPath)) {
    // Node.js project
    const nodeModulesPath = path.join(projectRoot, 'node_modules');
    if (!fs.existsSync(nodeModulesPath)) {
      warnings.push('node_modules not found - run npm install');
    }
  }

  if (fs.existsSync(pyprojectTomlPath)) {
    // Python project
    const venvPath = path.join(projectRoot, '.venv');
    const venvAltPath = path.join(projectRoot, 'venv');
    if (!fs.existsSync(venvPath) && !fs.existsSync(venvAltPath)) {
      warnings.push('Python virtual environment not found - consider creating one');
    }
  }

  // Check for git repository
  const gitPath = path.join(projectRoot, '.git');
  if (!fs.existsSync(gitPath)) {
    warnings.push('Git repository not found - version control not initialized');
  }

  return {
    passed: errors.length === 0,
    errors,
    warnings: warnings.length > 0 ? warnings : undefined
  };
}

/**
 * Run all verification checks
 * 
 * @param projectRoot - Root directory of the project
 * @param checks - Array of check types to run (default: all)
 * @returns Combined verification result
 * 
 * @example
 * ```typescript
 * const result = await verifyAll('/path/to/project', ['preCommit', 'environment']);
 * ```
 */
export async function verifyAll(
  projectRoot: string,
  checks: ('preCommit' | 'preDeployment' | 'environment')[] = ['preCommit', 'preDeployment', 'environment']
): Promise<VerificationResult> {
  const allErrors: string[] = [];
  const allWarnings: string[] = [];

  for (const check of checks) {
    let result: VerificationResult;

    switch (check) {
      case 'preCommit':
        result = await verifyPreCommit(projectRoot);
        break;
      case 'preDeployment':
        result = await verifyPreDeployment(projectRoot);
        break;
      case 'environment':
        result = await verifyEnvironment(projectRoot);
        break;
    }

    allErrors.push(...result.errors);
    if (result.warnings) {
      allWarnings.push(...result.warnings);
    }
  }

  return {
    passed: allErrors.length === 0,
    errors: allErrors,
    warnings: allWarnings.length > 0 ? allWarnings : undefined
  };
}

